		int tmp;
		int x,y;
		for(x=0;x<num-1;x++){
			for(y=x+1;y<num;y++){
				if(array[x]<array[y]){
					tmp = array[x];
					array[x]=array[y];
					array[y]=tmp;
				}
			}
		}
	}

}

