			in[i] = sc.nextInt();
		}
		sc.close();
		int[] result = top3(in);
		for(int i: result) System.out.println(i);
	}
	
	static int[] top3(int[] args) {
		int[] copy = Arrays.copyOf(args, args.length);
		Arrays.sort(copy);
		int[] result = new int[3];
