def sort(lst):
  for i in range(len(lst)):
    m = i
    for j in range(i+1,len(lst)):
      if lst[j] > lst[m]:
        m = j
    # swapping 
    tmp = lst[i]
    lst[i] = lst[m]
    lst[m] = tmp
  return lst

