// 194: Find Intersection of Two Unsorted Arrays
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <stdbool.h>
#include <math.h>
int main(void) {
    int m,n,a[500],b[500];
    scanf("%d%d",&m,&n);
    for(int i=0;i<m;++i)scanf("%d",&a[i]);
    for(int i=0;i<n;++i)scanf("%d",&b[i]);
    int out[1000],k=0;
    for(int i=0;i<m;++i) {
        bool seen=false;
        for(int j=0;j<k;++j)if(out[j]==a[i])seen=true;
        if(!seen)out[k++]=a[i];
    }
    int temp[1000],kk=0;
    for(int i=0;i<n;++i) {
        bool inA=false,dup=false;
        for(int j=0;j<m;++j)if(a[j]==b[i])inA=true;
        for(int j=0;j<kk;++j)if(temp[j]==b[i])dup=true;
        if(inA&&!dup)temp[kk++]=b[i];
    }
    for(int i=0;i<kk;++i)printf("%d%c",temp[i],i+1==kk?'\n':' ');
    return 0;
}

/*
 * P001205: Number of Longest Increasing Subsequences
 * Category: Dynamic Programming
 * Reads the input format described in the paired JSON problem file and prints the requested result.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

static int cmp_ll_asc(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (a > b) - (a < b);
}

static int cmp_ll_desc(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (b > a) - (b < a);
}

static void solve_number_of_longest_increasing_subsequences(void) {
    int n;
    if (scanf("%d", &n) != 1) return;
    long long *a = malloc((size_t)n * sizeof(long long));
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);
    qsort(a, n, sizeof(long long), cmp_ll_asc);
    for (int i = 0; i < n; ++i) printf("%lld%c", a[i], i + 1 == n ? '\n' : ' ');
    free(a);
}

int main(void) {
    solve_number_of_longest_increasing_subsequences();
    return 0;
}

