        for (int j = 0; j < i; j++) {
            if (nums[j] < nums[i]) {
                if (lengths[j] + 1 > lengths[i]) {
                    lengths[i] = lengths[j] + 1;
                    counts[i] = counts[j];
                } else if (lengths[j] + 1 == lengths[i]) {
                    counts[i] += counts[j];
                }
            }
        }
    }

    int maxLen = 0;
    for (int i = 0; i < numsSize; i++) maxLen = MAX(maxLen, lengths[i]);
    int ans = 0;
    for (int i = 0; i < numsSize; i++) {
        if (lengths[i] == maxLen) ans += counts[i];
    }
    return ans;
}

