void solveKT(int x, int y, int movei, vector<vector<int>>& sol) {
    if (movei == N * N) {
        found = true;
        return;
    }
    
    for (int k = 0; k < 8; ++k) {
        int next_x = x + dx[k];
        int next_y = y + dy[k];
        if (next_x >= 0 && next_x < N && next_y >= 0 && next_y < N && sol[next_x][next_y] == -1) {
            sol[next_x][next_y] = movei;
            solveKT(next_x, next_y, movei + 1, sol);
            if (found) return;
            sol[next_x][next_y] = -1;
        }
    }
}

