#define MAX(a, b) (((a) > (b)) ? (a) : (b))

int M, N;
int** forest;
int* dp;
int* dp2;
int** dist;
int* dx = {0, 1, 0, -1};
int* dy = {1, 0, -1, 0};

int dfs(int x, int y, int height) {
    if (x < 0 || x >= M || y < 0 || y >= N) {
        return INT_MAX;
    }
    if (forest[x][y] < height) {
        return INT_MAX;
    }
    if (dp[x * N + y] != -1) {
        return dp[x * N + y];
    }
    forest[x][y] = 0;
    int ret = height + dfs(x + dx[0], y + dy[0], height);
    for (int i = 1; i < 4; i++) {
        ret = MIN(ret, height + dfs(x + dx[i], y + dy[i], height));
    }
    forest[x][y] = 1;
    dp[x * N + y] = ret;
    return ret;
}

int dfs2(int x, int y) {
    if (x == M - 1 && y == N - 1) {
        return 0;
    }
    if (dp2[x * N + y] != -1) {
        return dp2[x * N + y];
    }
    int ret = INT_MAX;
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            if (forest[i][j] > dp[i * N + j]) {
                int cost = dist[i][j] + dfs2(i, j);
                ret = MIN(ret, cost);
            }
        }
    }
    dp2[x * N + y] = ret;
    return ret;
