    dp = (int*)malloc(sizeof(int) * M * N);
    dp2 = (int*)malloc(sizeof(int) * M * N);
    for (int i = 0; i < M; i++) {
        forest[i] = (int*)malloc(sizeof(int) * N);
    }
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            dp[i * N + j] = -1;
            dp2[i * N + j] = -1;
        }
    }
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &forest[i][j]);
        }
    }
    dist = (int**)malloc(sizeof(int*) * M);
    for (int i = 0; i < M; i++) {
