    }
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            scanf("%d", &dist[i][j]);
        }
    }
    int ans = INT_MAX;
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            if (forest[i][j] > 0) {
                int cost = dfs(i, j, forest[i][j]);
                ans = MIN(ans, dfs2(0, 0));
            }
        }
    }
    return (ans == INT_MAX) ? -1 : ans;
}

