#include <iostream>
#include <vector>
#include <queue>
#include <set>
#include <algorithm>
using namespace std;

int main() {
    int n, p, b;
    cin >> n >> p >> b;
    vector<bool> banned(n, false);
    for (int i = 0; i < b; ++i) { int x; cin >> x; if (0 <= x && x < n) banned[x] = true; }
    int k; cin >> k;

    vector<int> dist(n, -1);
    set<int> unused;
    for (int i = 0; i < n; ++i) if (!banned[i] && i != p) unused.insert(i);
    queue<int> q;
    dist[p] = 0;
    q.push(p);

    // For a reversal starting at s, the token lands at 2*s+k-1-x; reachable positions share one parity.
    // The ordered set lets us enumerate each newly reachable index only once.
    // Banned indices are excluded before the BFS begins.
    // Thus the total set work is O(n log n).
    while (!q.empty()) {
        int x = q.front(); q.pop();
        int loStart = max(0, x - k + 1);
        int hiStart = min(x, n - k);
        if (loStart > hiStart) continue;
        int lo = 2 * loStart + k - 1 - x;
        int hi = 2 * hiStart + k - 1 - x;
        int parity = (k - 1 - x) & 1;
        auto it = unused.lower_bound(lo);
        while (it != unused.end() && *it <= hi) {
            int y = *it;
            if ((y & 1) == parity) {
                dist[y] = dist[x] + 1;
                q.push(y);
                it = unused.erase(it);
            } else {
                ++it;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        if (i) cout << ' ';
        cout << dist[i];
    }
    return 0;
}

