    for (int r = 0; r < m; ++r) {
        for (int c = 0; c < n; ++c) {
            cin >> a[r][c];
            rows[r].insert(c);
            cols[c].insert(r);
        }
    }
    if (m == 1 && n == 1) { cout << 1; return 0; }

    vector<vector<int>> dist(m, vector<int>(n, -1));
    queue<pair<int, int>> q;
    dist[0][0] = 1;
    rows[0].erase(0);
    cols[0].erase(0);
    q.push({0, 0});

    // Each row/column set contains only unvisited cells, so every cell is removed once.
    // Row expansion covers every legal right move from the current cell.
    // Column expansion covers every legal downward move.
    // Removing a cell from both sets prevents duplicate discovery.
    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        int reach = a[r][c];

        auto rit = rows[r].lower_bound(c + 1);
        while (rit != rows[r].end() && *rit <= min(n - 1, c + reach)) {
            int nc = *rit;
            cols[nc].erase(r);
            dist[r][nc] = dist[r][c] + 1;
            if (r == m - 1 && nc == n - 1) { cout << dist[r][nc]; return 0; }
            q.push({r, nc});
            rit = rows[r].erase(rit);
        }

        auto cit = cols[c].lower_bound(r + 1);
        while (cit != cols[c].end() && *cit <= min(m - 1, r + reach)) {
            int nr = *cit;
            rows[nr].erase(c);
            dist[nr][c] = dist[r][c] + 1;
            if (nr == m - 1 && c == n - 1) { cout << dist[nr][c]; return 0; }
            q.push({nr, c});
            cit = cols[c].erase(cit);
        }
    }
    cout << -1;
    return 0;
}

