struct State { int r, c, dir; };

int main() {
    int n;
    cin >> n;
    vector<vector<int>> g(n, vector<int>(n));
    for (auto &row : g) for (int &x : row) cin >> x;
    vector<vector<array<int, 2>>> dist(n, vector<array<int, 2>>(n, {-1, -1}));
    queue<State> q;
    if (g[0][0] || g[0][1]) { cout << -1; return 0; }
    dist[0][0][0] = 0;
    q.push({0, 0, 0});
    // State stores the tail cell and orientation; BFS handles movement and both rotations uniformly.
    // A rotation is possible only when the 2x2 square around the snake is clear.
    // BFS guarantees the first target state uses the fewest moves.
    while (!q.empty()) {
        auto s = q.front(); q.pop();
        int d = dist[s.r][s.c][s.dir];
        int r2 = s.r + (s.dir == 1), c2 = s.c + (s.dir == 0);
        if (s.r == n - 1 && s.c == n - 2 && s.dir == 0) { cout << d; return 0; }
        if (s.dir == 0) {
            if (c2 + 1 < n && g[s.r][c2 + 1] == 0 && dist[s.r][s.c + 1][0] == -1) {
                dist[s.r][s.c + 1][0] = d + 1; q.push({s.r, s.c + 1, 0});
            }
            if (s.r + 1 < n && g[s.r + 1][s.c] == 0 && g[s.r + 1][c2] == 0) {
                if (dist[s.r + 1][s.c][0] == -1) { dist[s.r + 1][s.c][0] = d + 1; q.push({s.r + 1, s.c, 0}); }
                if (dist[s.r][s.c][1] == -1) { dist[s.r][s.c][1] = d + 1; q.push({s.r, s.c, 1}); }
            }
        } else {
            if (r2 + 1 < n && g[r2 + 1][s.c] == 0 && dist[s.r + 1][s.c][1] == -1) {
                dist[s.r + 1][s.c][1] = d + 1; q.push({s.r + 1, s.c, 1});
            }
            if (s.c + 1 < n && g[s.r][s.c + 1] == 0 && g[r2][s.c + 1] == 0) {
                if (dist[s.r][s.c + 1][1] == -1) { dist[s.r][s.c + 1][1] = d + 1; q.push({s.r, s.c + 1, 1}); }
                if (dist[s.r][s.c][0] == -1) { dist[s.r][s.c][0] = d + 1; q.push({s.r, s.c, 0}); }
            }
        }
    }
    cout << -1;
    return 0;
}

