using namespace std;

int bfs(const vector<vector<int>> &g, pair<int,int> src, pair<int,int> dst) {
    int m = g.size(), n = g[0].size();
    if (src == dst) return 0;
    if (g[src.first][src.second] == 0 || g[dst.first][dst.second] == 0) return -1;
    vector<vector<int>> d(m, vector<int>(n, -1));
    queue<pair<int,int>> q;
    q.push(src); d[src.first][src.second] = 0;
    const int dr[] = {-1,1,0,0}, dc[] = {0,0,-1,1};
    while (!q.empty()) {
        auto [r,c] = q.front(); q.pop();
        for (int z=0; z<4; ++z) {
            int nr=r+dr[z], nc=c+dc[z];
            if (nr>=0 && nr<m && nc>=0 && nc<n && g[nr][nc]>0 && d[nr][nc]==-1) {
                d[nr][nc]=d[r][c]+1;
                if (make_pair(nr,nc)==dst) return d[nr][nc];
                q.push({nr,nc});
            }
        }
    }
    return -1;
}

int main() {
    int m,n; cin>>m>>n;
    vector<vector<int>> g(m, vector<int>(n));
    vector<pair<int,pair<int,int>>> trees;
    for(int r=0;r<m;++r) for(int c=0;c<n;++c){
        cin>>g[r][c]; if(g[r][c]>1) trees.push_back({g[r][c],{r,c}});
    }
    sort(trees.begin(),trees.end());
    pair<int,int> cur={0,0};
    long long total=0;
    // Trees must be visited in height order, so each leg is the shortest path to the next tree.
    // BFS is restarted for each tree because the forest position changes after every cut.
    // Any unreachable tree makes the entire tour impossible.
    for(auto &t:trees){ int d=bfs(g,cur,t.second); if(d<0){cout<<-1;return 0;} total+=d; cur=t.second; }
    cout<<total;
    return 0;
}

