public class Main {
    // P000555 - Minimum Reverse Operations

    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[]h=br.readLine().trim().split("\\s+");
        int n=Integer.parseInt(h[0]),p=Integer.parseInt(h[1]),b=Integer.parseInt(h[2]);
        String[]ban=br.readLine().trim().split("\\s+");
        int k=Integer.parseInt(br.readLine().trim());
        boolean[]bad=new boolean[n];
        for(String x:ban)bad[Integer.parseInt(x)]=true;
        int[]d=new int[n];
        Arrays.fill(d,-1);
        if(bad[p]){
            for(int x:d)System.out.print(x+" ");
            return;
        }
        TreeSet<Integer> even=new TreeSet<>(),odd=new TreeSet<>();
        for(int i=0;i<n;i++)if(!bad[i]&&i!=p)( (i&1)==0?even:odd).add(i);
        Queue<Integer>q=new ArrayDeque<>();
        q.add(p);
        d[p]=0;
        while(!q.isEmpty()){
            int x=q.remove();
            int lo=Math.max(0,x-k+1),hi=Math.min(n-k,x);
            int first=lo*2+k-1-x;
            int last=hi*2+k-1-x;
            TreeSet<Integer>set=((first&1)==0)?even:odd;
            for(Integer y=set.ceiling(first);y!=null&&y<=last;){
                int ny=set.higher(y)==null?-1:set.higher(y);
                d[y]=d[x]+1;
                q.add(y);
                set.remove(y);
                y=ny;
            }
        }
        for(int i=0;i<n;i++){
            if(i>0)System.out.print(" ");
            System.out.print(d[i]);
        }
        System.out.println();
    }
}

