public class Main {
    // P000567 - Cut Off Trees for Golf Event

    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String[]h=br.readLine().trim().split("\\s+");
        int r=Integer.parseInt(h[0]),c=Integer.parseInt(h[1]);
        int[][]g=new int[r][c];
        List<int[]>trees=new ArrayList<>();
        for(int i=0;i<r;i++){
            String[]s=br.readLine().trim().split("\\s+");
            for(int j=0;j<c;j++){
                g[i][j]=Integer.parseInt(s[j]);
                if(g[i][j]>1)trees.add(new int[]{
                    g[i][j],i,j
                }
                );
            }
        }
        trees.sort(Comparator.comparingInt(x->x[0]));
        int cr=0,cc=0,total=0;
        for(int[]t:trees){
            int d=bfs(g,cr,cc,t[1],t[2]);
            if(d<0){
                System.out.println(-1);
                return;
            }
            total+=d;
            cr=t[1];
            cc=t[2];
        }
        System.out.println(total);
    }
    static int bfs(int[][]g,int sr,int sc,int tr,int tc){
        int r=g.length,c=g[0].length;
        Queue<int[]>q=new ArrayDeque<>();
        int[][]d=new int[r][c];
        for(int[]x:d)Arrays.fill(x,-1);
        q.add(new int[]{
            sr,sc
        }
        );
        d[sr][sc]=0;
        int[]dr={
            1,-1,0,0
        },dc={
            0,0,1,-1
        };
        while(!q.isEmpty()){
            int[]u=q.remove();
            if(u[0]==tr&&u[1]==tc)return d[u[0]][u[1]];
            for(int k=0;k<4;k++){
                int x=u[0]+dr[k],y=u[1]+dc[k];
                if(x>=0&&x<r&&y>=0&&y<c&&g[x][y]!=0&&d[x][y]<0){
                    d[x][y]=d[u[0]][u[1]]+1;
                    q.add(new int[]{
                        x,y
                    }
                    );
                }
            }
        }
        return -1;
    }
}

