public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int p = scanner.nextInt();
        int b = scanner.nextInt();
        int[] banned = new int[b];
        for (int i = 0; i < b; i++) {
            banned[i] = scanner.nextInt();
        }
        int k = scanner.nextInt();

        int[] result = minReverseOperations(n, p, banned, k);
        for (int i = 0; i < n; i++) {
            System.out.println(result[i]);
        }
    }

    public static int[] minReverseOperations(int n, int p, int[] banned, int k) {
        int[] result = new int[n];
        Arrays.fill(result, -1);
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(p);
        result[p] = 0;
        while (!queue.isEmpty()) {
            int current = queue.poll();
            for (int i = 1; i < k && current + i < n; i++) {
                if (Arrays.binarySearch(banned, 0, banned.length, current + i) < 0 && result[current + i] == -1) {
                    result[current + i] = result[current] + 1;
                    queue.offer(current + i);
                }
            }
            for (int i = 1; i < k && current - i >= 0; i++) {
                if (Arrays.binarySearch(banned, 0, banned.length, current - i) < 0 && result[current - i] == -1) {
                    result[current - i] = result[current] + 1;
                    queue.offer(current - i);
                }
            }
        }
        return result;
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int m = scanner.nextInt();
        int n = scanner.nextInt();
        int[][] grid = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        System.out.println(minCellsVisited(grid));
    }

    private static int minCellsVisited(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] directions = {{0, 1}, {1, 0}};
        boolean[][] visited = new boolean[m][n];
        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[2] - b[2]);
        queue.offer(new int[]{0, 0, 0});
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            if (cell[0] == m - 1 && cell[1] == n - 1) {
                return cell[2];
            }
            if (visited[cell[0]][cell[1]]) {
                continue;
            }
            visited[cell[0]][cell[1]] = true;
            for (int[] dir : directions) {
                int ni = cell[0] + dir[0] * grid[cell[0]][cell[1]];
                int nj = cell[1] + dir[1] * grid[cell[0]][cell[1]];
                if (ni < m && nj < n) {
                    queue.offer(new int[]{ni, nj, cell[2] + 1});
                }
            }
        }
        return -1;
    }
}

import java.util.*;

public class Main {
    static class Pair {
        int x, y, d, dir;
        Pair(int x, int y, int d, int dir) {
            this.x = x;
            this.y = y;
            this.d = d;
            this.dir = dir;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = sc.nextInt();
            }
        }
        System.out.println(minMoves(grid));
    }

    public static int minMoves(int[][] grid) {
        int n = grid.length;
        boolean[][][][] visited = new boolean[n][n][n][4];
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(0, 0, 0, 0));
        visited[0][0][0][0] = true;
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            if (cur.x == n - 1 && cur.y == n - 1) {
                return cur.d;
            }
            for (int i = 0; i < 4; i++) {
                int nx = cur.x, ny = cur.y, nd = cur.d;
                if (i < 2) {
                    nx += i == 0 ? 0 : 1;
                    ny += i == 0 ? 1 : 0;
                    nd++;
                } else {
                    int ndir = (cur.dir + (i == 2 ? 1 : -1) + 4) % 4;
                    nx += ">v<^".charAt(ndir) == '>' ? 1 : (ndir == 'v' ? -1 : 0);
                    ny += ">v<^".charAt(ndir) == 'v' ? 1 : (ndir == '<' ? -1 : 0);
                    nd++;
                }
                if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] == 0 && !visited[nx][ny][nd][(cur.dir + (i < 2 ? 0 : (i == 3 ? -1 : 1))) % 4]) {
                    queue.offer(new Pair(nx, ny, nd, (cur.dir + (i < 2 ? 0 : (i == 3 ? -1 : 1))) % 4));
                    visited[nx][ny][nd][(cur.dir + (i < 2 ? 0 : (i == 3 ? -1 : 1))) % 4] = true;
                }
            }
        }
        return -1;
    }
}

import java.util.*;

public class Main {
    private static final int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static int m, n;
    private static int[][] forest;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        m = scanner.nextInt();
        n = scanner.nextInt();
        forest = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                forest[i][j] = scanner.nextInt();
            }
        }
        System.out.println(cutOffTrees());
    }

    private static int cutOffTrees() {
        List<int[]> trees = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (forest[i][j] > 1) {
                    trees.add(new int[]{forest[i][j], i, j});
                }
            }
        }
        trees.sort(Comparator.comparingInt(a -> a[0]));
        int[] start = new int[]{1, 0, 0};
        int totalSteps = 0;
        for (int[] tree : trees) {
            int steps = minSteps(start, tree);
            if (steps == -1) {
                return -1;
            }
            totalSteps += steps;
            start = tree;
       }
        return totalSteps;
    }

    private static int minSteps(int[] start, int[] end) {
        Queue<int[]> queue = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        queue.offer(start);
        Set<String> visited = new HashSet<>();
        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            while (size-- > 0) {
                int[] cur = queue.poll();
                if (Arrays.equals(cur, end)) {
                    return cur[0];
                }
                for (int[] dir : dirs) {
                    int x = cur[1] + dir[0], y = cur[2] + dir[1];
                    if (x >= 0 && x < m && y >= 0 && y < n && forest[x][y] > 0 && !visited.contains(x + "," + y)) {
                        queue.offer(new int[]{cur[0] + 1, x, y});
                        visited.add(x + "," + y);
                    }
                }
            }
            steps++;
        }
        return -1;
    }
}

import java.util.*;
public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNextInt()) {
            int n = scanner.nextInt(), p = scanner.nextInt(), b = scanner.nextInt();
            boolean[] isBanned = new boolean[n];
            for (int i = 0; i < b; i++) isBanned[scanner.nextInt()] = true;
            int k = scanner.nextInt();
            int[] res = new int[n];
            Arrays.fill(res, -1);
            res[p] = 0;
            TreeSet<Integer>[] unvisited = new TreeSet[]{new TreeSet<Integer>(), new TreeSet<Integer>()};
            for (int i = 0; i < n; i++) {
                if (i != p && !isBanned[i]) unvisited[i % 2].add(i);
            }
            Queue<Integer> q = new LinkedList<>();
            q.add(p);
            while (!q.isEmpty()) {
                int cur = q.poll();
                int minIdx = Math.max(cur - k + 1, k - 1 - cur);
                int maxIdx = Math.min(cur + k - 1, 2 * n - k - 1 - cur);
                int parity = minIdx % 2;
                Integer nxt = unvisited[parity].ceiling(minIdx);
                List<Integer> toRemove = new ArrayList<>();
                while (nxt != null && nxt <= maxIdx) {
                    res[nxt] = res[cur] + 1;
                    q.add(nxt);
                    toRemove.add(nxt);
                    nxt = unvisited[parity].higher(nxt);
                }
                for (int x : toRemove) unvisited[parity].remove(x);
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < n; i++) sb.append(res[i]).append(i == n - 1 ? "" : " ");
            System.out.println(sb.toString());
        }
    }
}

