def min_reverse_operations(n, p, banned, k):
    banned = set(banned)
    operations = [0] * n
    for i in range(n):
        if i != p:
            if (i - p) % k == 0 and (i - p + k - 1) % k != 0 and i - p not in banned:
                operations[i] = operations[i - p] + 1
            elif (i - p - 1) % k == 0 and (i - p) not in banned:
                operations[i] = operations[i - p] + 1
            elif (i - p) % k != 0 and (i - p + k) not in banned:
                operations[i] = operations[i - p] + 1
            elif (i - p + k) not in banned:
                operations[i] = operations[i - p] + 1
            else:
                operations[i] = -1
        else:
            operations[i] = operations[i - p]
    return operations

def min_visited_cell(m, n, grid):
    visited = [[0 for _ in range(n)] for _ in range(m)]
    queue = [(0, 0)]
    dx = [0, 1, 0, -1]
    dy = [1, 0, -1, 0]
    
    while queue:
        x, y = queue.pop(0)
        if visited[x][y] == 1:
            continue
        visited[x][y] = 1
        if x == m - 1 and y == n - 1:
            return visited[x][y]
        for i in range(4):
            nx, ny = x + dx[i], y + dy[i]
            if 0 <= nx < m and 0 <= ny < n and visited[nx][ny] == 0 and visited[x][y] + grid[nx][ny] < visited[x][y] + grid[x][y]:
                queue.append((nx, ny))
    return -1

