public class Main {
    // P001359: Construct Lexicographically Largest Valid Sequence
    static int n;
    static int[] board;
    static boolean[] taken;

    static boolean place(int pos) {
        while (pos < board.length && board[pos] != 0) pos++;
        if (pos == board.length) return true;
        for (int v = n; v >= 1; --v) {
            if (taken[v]) continue;
            int second = pos + v;
            if (v != 1 && (second >= board.length || board[second] != 0)) continue;
            board[pos] = v;
            if (v != 1) board[second] = v;
            taken[v] = true;
            if (place(pos + 1)) return true;
            taken[v] = false;
            board[pos] = 0;
            if (v != 1) board[second] = 0;
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        board = new int[2 * n - 1];
        taken = new boolean[n + 1];
        place(0);
        for (int i = 0; i < board.length; i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(board[i]);
        }
    }
}

