        for(int i=n; i>=1; i--) {
            if(used[i]) continue;
            if(i == 1) {
                res[idx] = 1;
                used[1] = true;
                if(backtrack(idx+1)) return true;
                res[idx] = 0;
                used[1] = false;
            } else {
                int nextIdx = idx + i;
                if(nextIdx < 2*n-1 && res[nextIdx] == 0) {
                    res[idx] = i;
                    res[nextIdx] = i;
                    used[i] = true;
                    if(backtrack(idx+1)) return true;
                    res[idx] = 0;
                    res[nextIdx] = 0;
                    used[i] = false;
                }
            }
        }
        return false;
    }
}

