#include <string.h>

int calculate(int a, int b, char op) {
    switch (op) {
        case '+':
            return a + b;
        case '-':
            return a - b;
        case '*':
            return a * b;
    }
    return 0;
}

void solve(char* expression, int start, int end, int* results, int* resultSize) {
    if (start == end) {
        int num = expression[start] - '0';
        results[*resultSize] = num;
        (*resultSize)++;
        return;
    }
    for (int i = start; i < end; i++) {
        if (i != start && expression[start] == '+' && expression[i] == '+') {
            continue;
        }
        for (int j = i + 1; j <= end; j++) {
            if (j != i + 1 && expression[i] == '-' && expression[j] == '-') {
                continue;
            }
            int a = calculate(expression[start] - '0', expression[i + 1] - '0', expression[i]);
            int b = calculate(expression[j + 1] - '0', expression[end] - '0', expression[j]);
            int c = calculate(expression[start] - '0', b, expression[i]);
            int d = calculate(a, expression[end] - '0', expression[j]);
            int e = calculate(a, b, expression[i]);
            solve(expression, i + 1, j - 1, results, resultSize);
            solve(expression, start, j - 1, results, resultSize);
            solve(expression, i + 1, j - 1, results, resultSize);
            if (c == d && d == e && e == a) {
                results[*resultSize] = e;
                (*resultSize)++;
            }
        }
    }
}

int main() {
    char expression[256];
    scanf("%s", expression);
    int resultSize = 0;
    int* results = (int*)calloc(strlen(expression), sizeof(int));
    solve(expression, 0, strlen(expression) - 1, results, &resultSize);
    qsort(results, resultSize, sizeof(int), cmp);
    for (int i = 0; i < resultSize; i++) {
        printf("%d ", results[i]);
    }
    printf("\n");
    free(results);
    return 0;
}

