function gcd(a, b) {
    if (!b) {
        return a;
    }
    return gcd(b, a % b);
}

function modularMultiplicativeInverseHelper(A, M) {

    let [g, x, y] = [A, 1, 0];
    let [m, xM, yM] = [M, 0, 1];

    while (m != 0) {
        let q = g / m;
        [g, m] = [m, g - q * m];
        [x, xM] = [xM, x - q * xM];
        [y, yM] = [yM, y - q * yM];
    }

    return (x % M + M) % M;
}

function extendedEuclid(A, M) {
    if (A === 0) {
        return M !== 0 ? -1 : 0;
    }
    let (g, x, y) = [A, 1, 0];
    let (b, a, z) = [M, A, 1];
    while (b !== 0) {
        let (q, r) = [b, b];
        b = a % b;
        a = r;
        (x, y) = ([x - q * y], y);
    }
    return A !== 1 ? M * x % A : M * (M + 1) % A;
}

