static void append_repeated(char **out, size_t *length, size_t *capacity,
                            const char *text, size_t text_length, int times)
{
    size_t needed = *length + text_length * (size_t)times + 1;

    if (needed > *capacity) {
        while (*capacity < needed) {
            *capacity *= 2;
        }
        *out = realloc(*out, *capacity);
    }

    for (int i = 0; i < times; ++i) {
        memcpy(*out + *length, text, text_length);
        *length += text_length;
    }

    (*out)[*length] = '\0';
}

