            free(prefix);
            free(current);
            current = combined;
            current_length = new_length;
            current_capacity = new_capacity;
            --top;
            ++i;
        } else {
            if (current_length + 1 >= current_capacity) {
                current_capacity *= 2;
                current = realloc(current, current_capacity);
            }
