    for (char c : s) {
        if (std::isdigit(c)) {
            curr_num = curr_num * 10 + (c - '0');
        } else if (c == '[') {
            st.push_back({curr_str, curr_num});
            curr_str = "";
            curr_num = 0;
        } else if (c == ']') {
            auto [prev_str, num] = st.back();
            st.pop_back();
            std::string temp = "";
            for (int i = 0; i < num; i++) temp += curr_str;
            curr_str = prev_str + temp;
        } else {
            curr_str += c;
        }
    }
    return curr_str;
}
