#include <limits.h>

static int cmp_ll_asc(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (a > b) - (a < b);
}

static int cmp_ll_desc(const void *pa, const void *pb) {
    long long a = *(const long long *)pa;
    long long b = *(const long long *)pb;
    return (b > a) - (b < a);
}

static void solve_product_except_self(void) {
    int n;
    if (scanf("%d", &n) != 1) return;
    long long *a = malloc((size_t)n * sizeof(long long));
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);
    qsort(a, n, sizeof(long long), cmp_ll_asc);
    for (int i = 0; i < n; ++i) printf("%lld%c", a[i], i + 1 == n ? '\n' : ' ');
    free(a);
}

int main(void) {
    solve_product_except_self();
    return 0;
}

#include <stdio.h>

void productArray(int arr[], int n) {
    int left[n], right[n], prod[n];
    left[0] = 1;
    right[n-1] = 1;
    prod[0] = arr[0];
    prod[n-1] = arr[n-1];

    for(int i = 1; i < n; i++) {
        left[i] = arr[i] * left[i-1];
    }

    for(int i = n-2; i >= 0; i--) {
        right[i] = arr[i] * right[i+1];
    }

    for(int i = 0; i < n; i++) {
        prod[i] = left[i] * right[i];
    }

    for(int i = 0; i < n; i++) {
        printf("%d ", prod[i]);
    }
}

