def product_array(N, nums):
    prefix, suffix = [1]*N, [1]*N

    for i in range(N):
        if i > 0:
            prefix[i] = nums[i-1] * prefix[i-1]
    for i in range(N-1, -1, -1):
        if i < N-1:
            suffix[i] = nums[i+1] * suffix[i+1]

    for i in range(N):
        if i == 0:
            suffix[i] = suffix[i+1]
        elif i == N-1:
            prefix[i] = prefix[i-1]
        else:
            prefix[i] = prefix[i-1] * suffix[i+1]

    return prefix

