typedef struct {
    int vertex;
    int weight;
    struct Node* next;
} Node;

typedef struct {
    int value;
    Node* head;
} Graph;

Graph* createGraph(int V) {
    Graph* graph = malloc(sizeof(Graph));
    graph->value = V;
    graph->head = NULL;
    return graph;
}

Node* createNode(int v, int w) {
    Node* newNode = malloc(sizeof(Node));
    newNode->vertex = v;
    newNode->weight = w;
    newNode->next = NULL;
    return newNode;
}

void addEdge(Graph* graph, int src, int dest, int weight) {
    Node* newNode = createNode(dest, weight);
    newNode->next = graph->head;
    graph->head = newNode;
}

Graph* cloneGraph(Graph* graph) {
    Graph* clonedGraph = createGraph(graph->value);
    Node* current = graph->head;
    while (current != NULL) {
        addEdge(clonedGraph, graph->value, current->vertex, current->weight);
        current = current->next;
    }
    return clonedGraph;
}

