    printf("Cloned Graph:\n");
    Node* clonedCurrent = clonedGraph->head;
    while (clonedCurrent != NULL) {
        printf("%d -> %d (weight: %d)\n", clonedCurrent->vertex, clonedCurrent->next->vertex, clonedCurrent->next->weight);
