#include <stdio.h>
#include <stdlib.h>

typedef struct edge{
    int u;
    int v;
    int type;
    struct edge* next;
}Edge;

Edge* newEdge(int u, int v, int type){
    Edge* edge = (Edge*)malloc(sizeof(Edge));
    edge->u = u;
    edge->v = v;
    edge->type = type;
    edge->next = NULL;
    return edge;
}

void addEdge(Edge** head, int u, int v, int type){
    Edge* edge = newEdge(u, v, type);
    edge->next = *head;
}

void printList(Edge* head){
    while(head){
        printf("%d %d %d\n", head->u, head->v, head->type);
        head = head->next;
    }
}

int main(){
    int N, M;
    scanf("%d %d", &N, &M);

    Edge* head[N+1];
    for(int i=1; i<=N; i++){
        head[i] = NULL;
    }

    for(int i=0; i<M; i++){
        int type, u, v;
        scanf("%d %d %d", &type, &u, &v);
        addEdge(&head[u], u, v, type);
        addEdge(&head[v], v, u, type);
    }

    int count[N+1];
    for(int i=1; i<=N; i++){
        count[i] = 0;
    }

    for(int i=1; i<=N; i++){
        Edge* temp = head[i];
        while(temp){
            if(temp->type == 1 && count[temp->v] == 0 || temp->type == 2 && count[temp->u] == 0){
                count[temp->v]++;
            }
            temp = temp->next;
        }
    }

    int sum = 0;
    for(int i=1; i<=N; i++){
        sum += count[i];
    }

    if(sum>0){
        printf("%d\n", sum);
    }
    else{
        printf("-1\n");
    }

    return 0;
}

#include <stdlib.h>
#include <stdbool.h>

bool dfs(int u, int** graph, int* graphColSize, int* color) {
    color[u] = 1;
    for (int i = 0; i < graphColSize[u]; i++) {
        int v = graph[u][i];
        if (color[v] == 1 || (color[v] == 0 && !dfs(v, graph, graphColSize, color))) {
            return false;
        }
    }
    color[u] = 2;
    return true;
}

