    parent_b = list(range(n + 1))
    rank_a = [0] * (n + 1)
    rank_b = [0] * (n + 1)
    
    def find(par, x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
        
    def union(par, rank, x, y):
        rx, ry = find(par, x), find(par, y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            par[rx] = ry
        elif rank[rx] > rank[ry]:
            par[ry] = rx
        else:
            par[ry] = rx
            rank[rx] += 1
        return True
        
    removed = 0
    
    # Process Type 3 first
    for u, v in type3:
        if not union(parent_a, rank_a, u, v):
            removed += 1
        else:
            union(parent_b, rank_b, u, v)
            
    # Process Type 1
