Node* sortedMerge(Node* l1, Node* l2) {
    if (!l1) {
        return l2;
    }
    if (!l2) {
        return l1;
    }

    Node* result = NULL;

    if (l1->data < l2->data) {
        result = l1;
        l1 = l1->next;
    } else {
        result = l2;
        l2 = l2->next;
    }

    Node* current = result;

    while (l1 != result && l2 != result) {
        if (l1->data < l2->data) {
            current->next = l1;
            l1 = l1->next;
        } else {
            current->next = l2;
            l2 = l2->next;
        }
        current = current->next;
    }

    if (l1 != result) {
        current->next = l1;
    } else {
        current->next = l2;
    }

    return result;
}

