        speedSum += engineers[i].spd;
        if (heapSize > k) {
            speedSum -= popMin(heap, &heapSize);
        }
        long long cur = speedSum * engineers[i].eff;
        if (cur > best) best = cur;
    }
    free(engineers);
    free(heap);
    return (int)(best % MOD);
}

