import java.io.*;
import java.util.*;

public class Main {
    static class Node {
        int data;
        Node left, right;

        Node(int item) {
            data = item;
            left = right = null;
        }
    }

    static Node insert(Node node, int data) {
        if (node == null) {
            return new Node(data);
        }

        if (data < node.data) {
            node.left = insert(node.left, data);
        } else if (data > node.data) {
            node.right = insert(node.right, data);
        }

        return node;
    }

    static void inorder(Node root) {
        if (root != null) {
            inorder(root.left);
            System.out.print(root.data + " ");
            inorder(root.right);
        }
    }

    static Node mergeTrees(Node root1, Node root2) {
        if (root1 == null) {
            return root2;
        }
        if (root2 == null) {
            return root1;
        }

        root1.data += root2.data;
        root1.left = mergeTrees(root1.left, root2.left);
        root1.right = mergeTrees(root1.right, root2.right);

        return root1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n1 = sc.nextInt();
        Node root1 = null;
        while (n1-- > 0) {
            root1 = insert(root1, sc.nextInt());
        }

        int n2 = sc.nextInt();
        Node root2 = null;
        while (n2-- > 0) {
            root2 = insert(root2, sc.nextInt());
        }

        Node mergedTree = mergeTrees(root1, root2);
        inorder(mergedTree);
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

public class Solution {
    public TreeNode[] splitBST(TreeNode root, int target) {
        if (root == null) return new TreeNode[]{null, null};

        if (root.val <= target) {
            TreeNode[] res = splitBST(root.right, target);
            root.right = res[0];
            return new TreeNode[]{root, res[1]};
        } else {
            TreeNode[] res = splitBST(root.left, target);
            root.left = res[1];
            return new TreeNode[]{res[0], root};
        }
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}

public class Solution {
    private TreeNode insert(TreeNode node, int val) {
        if (node == null) return new TreeNode(val);
        if (val < node.val) node.left = insert(node.left, val);
        else node.right = insert(node.right, val);
        return node;
    }

    private void addAll(TreeNode root1, TreeNode node) {
