        else: v=int(a[p]); l=int(a[p+1]); r=int(a[p+2]); p+=3
        nodes[i]=Node(v); L[i]=l; RR[i]=r
    for i in range(n):
        if L[i]>0: nodes[i].l=nodes[L[i]-1]
        if RR[i]>0: nodes[i].r=nodes[RR[i]-1]
    return nodes[0],nodes,p

