            result.push_back(lower[-1]);
            lower--;
        } else {
            if(abs(x - lower[-1]) < abs(x - upper[-1]))
                result.push_back(lower[-1]);
            else
                result.push_back(upper[-1]);

            if(lower[-1] == upper[-1])
