function binarySearch(nums, target, start, end) {
  if(start > end) {
    return -1;
  }
  let mid = Math.floor((start + end) / 2);
  if(nums[mid] == target) {
    return mid;
  } else if(nums[mid] > target) {
    return binarySearch(nums, target, start, mid - 1);
  } else {
    return binarySearch(nums, target, mid + 1, end);
  }
}

