struct graph {
    struct edge* edges;
    int V;
    int E;
};

struct subset {
    int parent;
    int rank;
};

int cmpfunc(const void * a, const void * b) {
   return (((struct edge *)a)->weight - ((struct edge *)b)->weight);
}

void make_set(struct subset *s, int v) {
    s->parent = v;
    s->rank = 0;
}

int find(struct subset *s, int v) {
    while(s[v].parent != v) v = s[v].parent;
    return v;
}

void union_set(struct subset *s, int u, int v) {
    int u_rank = s[u].rank;
    int v_rank = s[v].rank;

    if (u_rank > v_rank) {
        s[v].parent = u;
    } else if (u_rank < v_rank) {
        s[u].parent = v;
    } else {
        s[v].parent = u;
        s[u].rank++;
    }
}

int is_cyclic(struct graph *g, int v, int u) {
    return find(g->subsets, v) == find(g->subsets, u);
}

void kruskal_mst(struct graph *g) {
    qsort(g->edges, g->E, sizeof(g->edges[0]), cmpfunc);

    int total_weight = 0;
    int E = 0;

    while(E < g->V - 1) {
        struct edge next_edge = g->edges[E++];

        if(!is_cyclic(g, next_edge.src, next_edge.dest)) {
            printf("%d -- %d == %d\n", next_edge.src, next_edge.dest, next_edge.weight);
            total_weight += next_edge.weight;
            union_set(g->subsets, next_edge.src, next_edge.dest);
        }
    }

    printf("Weight of Minimum Spanning Tree: %d\n", total_weight);
}

