class UnionFind {
private:
    vector<int> par, rank;
public:
    UnionFind(int n) {
        par.resize(n);
        rank.resize(n);
        for (int i = 0; i < n; i++) {
            par[i] = i;
        }
    }

    int find(int x) {
        if (par[x] != x) {
            par[x] = find(par[x]);
        }
        return par[x];
    }

    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y)
            return;
        if (rank[x] < rank[y])
            swap(x, y);
        par[y] = x;
        if (rank[x] == rank[y])
            rank[x]++;
    }

    bool same(int x, int y) {
        x = find(x), y = find(y);
        return x == y;
    }
};

