class UnionFind {
    constructor(n) {
        this.parent = new Array(n);
        this.size = new Array(n).fill(-1);
        for(let i = 0; i < n; i++) {
            this.parent[i] = i;
        }
    }

    find(x) {
        if(this.parent[x] != x) {
            this.parent[x] = this.find(this.parent[x]);
        }
        return this.parent[x];
    }

    union(x, y) {
        x = this.find(x);
        y = this.find(y);
        if(x != y) {
            if(this.size[x] < this.size[y]) {
                let temp = x;
                x = y;
                y = temp;
            }
            this.parent[y] = x;
            this.size[x] += this.size[y];
        }
    }
}

function solve(N, M, edges) {
    let unionFind = new UnionFind(N);
    let totalWeight = 0;
    for(let i = 0; i < M; i++) {
        let [u, v, w] = edges[i];
        totalWeight += w;
        unionFind.union(u, v);
    }
    return totalWeight;
}

