class UnionFind:
    def __init__(self, N):
        self.p = list(range(N))
        self.rank = [0] * N

    def find(self, x):
        if self.p[x] != x:
            self.p[x] = self.find(self.p[x])
        return self.p[x]

    def union(self, x, y):
        rx, ry = self.find(x), self.find(y)
        if rx != ry:
            self.p[rx] = ry
            if self.rank[rx] < self.rank[ry]:
                self.p[ry] = rx
            else:
                self.p[rx] = ry
                if self.rank[ry] == self.rank[rx]:
                    self.rank[ry] += 1

def solve(N, M, edges):
    edges.sort(key=lambda x: x[2])

    uf = UnionFind(N)
    weight = 0
    for u, v, w in edges:
        if uf.find(u) != uf.find(v):
            uf.union(u, v)
            weight += w

    return weight

