struct Node* arrangeList(struct Node* head) {
    if (head == NULL || head->next == NULL) {
        return head;
    }

    struct Node* slow = head;
    struct Node* fast = head->next;

    while (fast != NULL) {
        slow = slow->next;
        fast = fast->next;
        if (fast != NULL) {
            fast = fast->next;
        }
    }

    struct Node* second = slow->next;
    slow->next = NULL;
    second->next = NULL;

    struct Node* first = head;
    struct Node* temp_first = first;
    struct Node* temp_second = second;

    int len = 0;
    while (first != NULL) {
        first = first->next;
        len++;
    }

    first = temp_first;
    second = temp_second;

    struct Node* new_head = (struct Node*) malloc(sizeof(struct Node));
    new_head = arrangeList(first);

    struct Node* ptr;
    if (len % 2 == 0) {
        while (temp_first != NULL) {
            ptr = newNode(temp_first->data);
            ptr->next = temp_second->next;
            temp_second->next = ptr;
            temp_second = ptr;
            temp_first = temp_first->next;
        }
    } else {
        while (temp_first != second) {
            ptr = newNode(temp_first->data);
            ptr->next = temp_second->next;
            temp_second->next = ptr;
            temp_second = ptr;
            temp_first = temp_first->next;
        }
        ptr = newNode(second->data);
        ptr->next = temp_second->next;
        temp_second->next = ptr;
    }

    return new_head;
}

