class LinkedList {
public:
    Node* head;

    LinkedList() : head(NULL) {}

    void push(int data) {
        Node* newNode = new Node();
        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }

    void print() {
        Node* temp = head;
        while (temp) {
            cout << temp->data << " ";
            temp = temp->next;
        }
        cout << endl;
    }

    void rearrange() {
        Node* current = head;
        Node* end = head;
        bool fromLeft = true;

        while (end->next) {
            end = end->next;
        }

        while (current != end && current != end->next) {
            if (fromLeft) {
                if (current == head) {
                    head = current->next;
                } else {
                    Node* nextNode = current->next;
                    current->next = current->next->next;
                    nextNode->next = end->next;
                    end->next = nextNode;
                }
            } else {
                if (current == head) {
                    head = current->next;
                } else {
                    Node* prevNode = current->next;
                    current->next = current->next->next;
                    prevNode->next = end->next;
                    end->next = prevNode;
                }
            }

            current = current->next;
            fromLeft = !fromLeft;
        }
    }
};

