vector<string> split(const string& line) {
    vector<string> fields;
    string field;
    stringstream input(line);
    while (getline(input, field, '|')) {
        fields.push_back(field);
    }
    return fields;
}

string lowerCopy(string value) {
    transform(value.begin(), value.end(), value.begin(),
              [](unsigned char c) { return static_cast<char>(tolower(c)); });
    return value;
}

bool isTrue(const string& value) {
    string v = lowerCopy(value);
    return v == "yes" || v == "true" || v == "1" || v == "available" ||
           v == "active" || v == "online" || v == "vacant";
}

double number(const string& value) {
    return stod(value);
}

bool startsWith(const string& value, const string& prefix) {
    return value.size() >= prefix.size() &&
           value.compare(0, prefix.size(), prefix) == 0;
}

bool endsWith(const string& value, const string& suffix) {
    return value.size() >= suffix.size() &&
           value.compare(value.size() - suffix.size(), suffix.size(), suffix) == 0;
}

