void bfs() {
    int head, tail;
    for (head = 0, tail = 0; head < tail; ++tail) {
        if (strcmp(beginWord, wordList[tail]) == 0) {
            visited[tail] = 1;
        }
        else {
            int i;
            for (i = 0; i < wordListSize; ++i) {
                if (visited[i] == 0 && strlen(wordList[i]) == strlen(wordList[tail]) - 1) {
                    strcpy(dist[tail], wordList[i]);
                    strcat(dist[tail], beginWord);
                    visited[i] = 1;
                    head += 1;
                    if (strcmp(wordList[i], endWord) == 0) {
                        return;
                    }
                }
            }
        }
    }
}

