#include <queue>
using namespace std;

int main() {
    string beginWord, endWord;
    int n;
    cin >> beginWord >> endWord >> n;
    unordered_set<string> dict;
    for (int i = 0; i < n; ++i) { string w; cin >> w; dict.insert(w); }
    if (beginWord == endWord) { cout << 1; return 0; }
    if (!dict.count(endWord)) { cout << 0; return 0; }

    queue<string> q;
    q.push(beginWord);
    int level = 1;
    // Generate one-letter neighbors and mark them immediately so each word enters the BFS once.
    // BFS levels correspond directly to transformation-sequence length.
    // Removing a discovered word avoids repeated work across neighboring words.
    while (!q.empty()) {
        int sz = q.size(); ++level;
        while (sz--) {
            string w = q.front(); q.pop();
            for (int i = 0; i < (int)w.size(); ++i) {
                char old = w[i];
                for (char c = 'a'; c <= 'z'; ++c) {
                    if (c == old) continue;
                    w[i] = c;
                    if (w == endWord) { cout << level; return 0; }
                    if (dict.erase(w)) q.push(w);
                }
                w[i] = old;
            }
        }
    }
    cout << 0;
    return 0;
}

