using namespace std;

int main() {
    int target;
    cin >> target;
    const int INF = 1e9;
    vector<int> dp(target + 1, INF);
    dp[0] = 0;
    // Use the shortest acceleration prefix that passes the target, then consider reversing earlier.
    for (int t = 1; t <= target; ++t) {
        int n = 1;
        while ((1 << n) - 1 < t) ++n;
        int full = (1 << n) - 1;
        if (full == t) {
            dp[t] = n;
            continue;
        }
        // Overshoot to the first position beyond t, reverse, and solve the remaining distance.
        // Trying a reverse before the full acceleration prefix can produce a shorter route.
        dp[t] = n + 1 + dp[full - t];
        int prevFull = (1 << (n - 1)) - 1;
        for (int back = 0; back <= n - 2; ++back) {
            int pos = prevFull - ((1 << back) - 1);
            int remaining = t - pos;
            if (remaining >= 0) {
                dp[t] = min(dp[t], (n - 1) + 1 + back + 1 + dp[remaining]);
            }
        }
    }
    cout << dp[target];
    return 0;
}

