        while (!queue.isEmpty()) {
            int[] curr = queue.poll();
            if (curr[0] == target) {
                return curr[2];
            }
            if (curr[1] > 0) {
                queue.offer(new int[]{curr[0] + curr[1], curr[1] * 2, curr[2] + 1});
            }
            if (curr[1] < 0) {
                queue.offer(new int[]{curr[0] + curr[1], curr[1] * 2, curr[2] + 1});
            }
            queue.offer(new int[]{curr[0], -curr[1], curr[2] + 1});
        }

        return -1;
    }
