int countPaths(int N, int M, int grid[N][M]) {
    int dp[N][M];

    for(int i = 0; i < N; i++) {
        for(int j = 0; j < M; j++) {
            if(i==0 || j==0) {
                dp[i][j] = 1;
            } else {
                dp[i][j] = dp[i-1][j] + dp[i][j-1];
            }
        }
    }

    return dp[N-1][M-1];
}

