public class Main {
    public static int countPaths(int[][] maze, int n, int m) {
        if (maze[0][0] == 0 || maze[n-1][m-1] == 0) {
            return 0;
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (maze[i][j] == 1) {
                    maze[i][j] = 0;
                    if (i < n-1) {
                        maze[i+1][j] += maze[i][j];
                    }
                    if (j < m-1) {
                        maze[i][j+1] += maze[i][j];
                    }
                }
            }
        }
        return maze[n-1][m-1];
    }

