int longestUncommonSubsequence(char* A, char* B) {
    int lenA = strlen(A);
    int lenB = strlen(B);

    if (lenA == 0 || lenB == 0) {
        return -1;
    }

    if (strcmp(A, B) == 0) {
        return -1;
    }

    return lenA > lenB ? lenA : lenB;
}

