#include <stdio.h>
#include <stdlib.h>

struct ListNode {
    int val;
    struct ListNode *next;
};

struct ListNode* rotateRight(struct ListNode* head, int k) {
    if (head == NULL || head->next == NULL || k == 0) return head;

    struct ListNode *node = head;
    int len = 1;

    while (node->next != NULL) {
        node = node->next;
        len++;
    }

    node->next = head;
    node = head;

