var rotateRight = function(head, k) {
  if (!head || !head.next || k <= 0) return head;

  let fast = head, slow = head;
  while (fast.next) {
    fast = fast.next;
    if (fast.next) {
      slow = slow.next;
      fast = fast.next;
    }
  }
  let tail = slow;

  let newTail = tail.next;
  tail.next = null;

  newTail.next = head;

  if (k == 1) {
    return newTail;
  } else {
    while (k > 1) {
      k--;
      newTail = newTail.next;
    }
    return newTail;
  }
};

