    }

    if (n == 1) {
        if (nums[0] == target) {
            printf("0\n");
        } else {
            printf("-1\n");
        }
        return;
    }

    if (target < nums[0] || target > nums[n - 1]) {
        printf("-1\n");
        return;
    }

    int sum = nums[0];
    for (int i = 1; i < n; i++) {
        if (sum + nums[i] <= target) {
            sum += nums[i];
        } else {
            if (sum == target) {
                printf("0\n");
                return;
            }
            printf("-1\n");
            return;
        }
    }

    if (sum == target) {
        printf("0\n");
    } else {
        printf("-1\n");
    }
}

