public class Main {
    static class FS {
        private final InputStream in = System.in;
        private final byte[] b = new byte[1 << 16];
        private int p=0,n=0;
        int read() throws IOException {
            if(p>=n){
                n=in.read(b);
                p=0;
                if(n<0)return -1;
            }
            return b[p++];
        }
        String next() throws IOException {
            StringBuilder s=new StringBuilder();
            int c;
            do{
                c=read();
            } while(c<=32 && c!=-1);
            while(c>32 && c!=-1){
                s.append((char)c);
                c=read();
            }
            return s.toString();
        }
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
    static void outArr(int[] a) {
        for(int i=0;i<a.length;i++){
            if(i>0) System.out.print(" ");
            System.out.print(a[i]);
        }
        System.out.println();
    }
    static void outLongArr(long[] a) {
        for(int i=0;i<a.length;i++){
            if(i>0) System.out.print(" ");
            System.out.print(a[i]);
        }
        System.out.println();
    }

    static char solve(String s,long k,int i,long len){
        if(i<0)return '?';
        char c=s.charAt(i);
        if(Character.isLetter(c)){
            if(k==len)return c;
            return solve(s,k,i-1,len-1);
        }
        long prev=len/(c-'0');
        long kk=(k-1)%prev+1;
        return solve(s,kk,i-1,prev);
    }
    public static void main(String[] z)throws Exception{
        FS f=new FS();
        String s=f.next();
        long k=f.nextLong(),len=0;
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);
            if(Character.isLetter(c))len++;
            else len=Math.min(Long.MAX_VALUE/2,len*(c-'0'));
        }
        System.out.println(solve(s,k,s.length()-1,len));
    }
}

