def decodeAtIndex(s: str, K: int) -> str:
    def get_length(s):
        length = 0
        for c in s:
            if c.isalpha():
                length += 1
            else:
                length += int(c)
        return length

    length = get_length(s)
    mod = length  

    def decode(s, K):
        nonlocal mod
        for c in s:
            if c.isdigit():
                K *= int(c)
                K %= mod
            else:
                if K == 0:
                    return c
                K -= 1

    return decode(s, K)


