int visit[10000];
int bfs(int start, int end) {
    int wheel[4];
    int next[4], dir[4];
    memset(next, -1, sizeof(next));
    memset(dir, 0, sizeof(dir));

    wheel[0] = start / 1000;
    wheel[1] = (start % 1000) / 100;
    wheel[2] = (start % 100) / 10;
    wheel[3] = start % 10;

    int step = 0;
    while (step < 4) {
        if (wheel[step] == end / 1000) {
            return step;
        }
        int cur = wheel[step];
        if (next[step] != -1 && visit[next[step]] == 0) {
            dir[step] = 1 - dir[step];
            visit[next[step]] = 1;
            wheel[step] += dir[step];
            if (wheel[step] == 10) {
                wheel[step] = 0;
            }
            continue;
        }
        if (cur < 10) {
            next[step] = cur + 10 * dir[step];
            dir[step] = 1 - dir[step];
        } else if (cur == 10) {
            next[step] = cur - 10 * dir[step];
            dir[step] = 1 - dir[step];
        } else {
            next[step] = cur * 10;
        }
        visit[next[step]] = 1;
        wheel[step] += dir[step];
        if (wheel[step] == 10) {
            wheel[step] = 0;
        }
        step++;
    }
    return -1;
}

