    public static int firstMissingPositive(int[] nums) {
        int n = nums.length;

        if (n == 0) {
            return 1;
        }

        for (int i = 0; i < n; i++) {
            if (nums[i] <= 0) {
                nums[i] = Integer.MAX_VALUE;
            }

           if (nums[i] > n) {
               nums[i] = Integer.MAX_VALUE;
           }
        }

        for (int i = 0; i < n; i++) {
           int num = Math.abs(nums[i]);
           if (num == Integer.MAX_VALUE) {
               continue;
           }
           num--;
           if (nums[num] > 0) {
               nums[num] = -nums[num];
           }
        }

        for (int i = 0; i < n; i++) {
           if (nums[i] >= 0) {
               return i + 1;
           }
        }

        return n + 1;
    }
}

