function findSmallestMissingPositive(arr) {
    let n = arr.length;
    if (n == 0) {
        return 1;
    }

    let positiveCount = 0;
    for (let i = 0; i < n; i++) {
        if (arr[i] > 0) {
            positiveCount++;
        }
    }

    if (positiveCount == 0) {
        return 1;
    }

    let containsOne = false;
    for (let i = 0; i < n; i++) {
        if (arr[i] == 1) {
            containsOne = true;
        }
        if (arr[i] <= 0) {
            arr[i] = 1;
        }
    }

    if (!containsOne) {
        return 1;
    }

    for (let i = 0; i < n; i++) {
        let a = Math.abs(arr[i]);
        if (a == n) {
            arr[0] = -Math.abs(arr[0]);
        } else {
            arr[a] = -Math.abs(arr[a]);
        }
    }

    for (let i = 1; i < n; i++) {
        if (arr[i] > 0) {
            return i;
        }
    }

    if (arr[0] > 0) {
        return n;
    }

    return n + 1;
}

