typedef struct Node {
    int data;
    struct Node *left, *right;
} Node;

Node* newNode(int data) {
    Node* node = (Node*) malloc(sizeof(Node));
    node->data = data;
    node->left = node->right = NULL;
    return node;
}

Node* insert(Node* node, int data) {
    if (node == NULL) return newNode(data);
    if (data < node->data)
        node->left = insert(node->left, data);
    else if (data > node->data)
        node->right = insert(node->right, data);
    return node;
}

int findMaxXOR(Node* root, int num) {
    if (root == NULL) return -1;
    if (root->data == num) return root->data;
    if (root->data < num) return findMaxXOR(root->right, num);
    return findMaxXOR(root->left, num);
}

int maxXOR(int arr[], int n) {
    Node* root = NULL;
    for (int i = 0; i < n; i++) {
        root = insert(root, arr[i]);
    }
    int maxXOR = 0;
    for (int i = 0; i < n; i++) {
        int xor = findMaxXOR(root, arr[i]);
        maxXOR = (xor > maxXOR) ? xor : maxXOR;
    }
    return maxXOR;
}

