    return 0;
  }

  let arr = Array.from(Array(n + 1), () => Array(r + 1).fill(0));

  arr[0][0] = 1;

  for (let i = 1; i <= n; i++) {
    arr[i][0] = 1;
    for (let j = 1; j <= r; j++) {
      arr[i][j] = arr[i - 1][j - 1] + arr[i - 1][j];
    }
  }

  return arr[n][r];
