#include <stdio.h>
#include <string.h>

int is_palindrome(char* str, int len) {
    int start = 0;
    int end = len - 1;
    while (start < end) {
        if (str[start] != str[end]) {
            return 0;
        }
        start++;
        end--;
    }
    return 1;
}

int main() {
    char A[1001], B[1001];
    scanf("%s%s", A, B);
    int len = strlen(A) + strlen(B) + 1;
    if (is_palindrome(A, len) && is_palindrome(B, len)) {
        printf("Yes\n");
    } else {
        printf("No\n");
    }
    return 0;
}

