bool isPalindrome(const char* s, int i, int j) {
    while (i < j) {
        if (s[i++] != s[j--]) return false;
    }
    return true;
}

bool check(const char* a, const char* b) {
    int i = 0, j = strlen(a) - 1;
    while (i < j && a[i] == b[j]) {
        i++;
        j--;
    }
    return isPalindrome(a, i, j) || isPalindrome(b, i, j);
}

