using namespace std;

bool palindrome(const string &s, int left, int right) {
    while (left < right) {
        if (s[left] != s[right]) return false;
        ++left;
        --right;
    }
    return true;
}

bool check(const string &a, const string &b) {
    int left = 0;
    int right = static_cast<int>(a.size()) - 1;

    while (left < right && a[left] == b[right]) {
        ++left;
        --right;
    }

    return left >= right ||
           palindrome(a, left, right) ||
           palindrome(b, left, right);
}

int main() {
    string a, b;
    cin >> a >> b;
    cout << (check(a, b) || check(b, a) ? "Yes" : "No");
    return 0;
}

