// Try both prefix/suffix orientations and finish with a palindrome check on the unmatched middle.
public class Main {
    static boolean pal(String s,int l,int r){
        while(l<r)if(s.charAt(l++)!=s.charAt(r--))return false;
        return true;
    }
    static boolean check(String a,String b){
        int i=0,j=a.length()-1;
        while(i<j&&a.charAt(i)==b.charAt(j)){
            i++;
            j--;
        }
        return i>=j||pal(a,i,j)||pal(b,i,j);
    }
    public static void main(String[] args)throws Exception{
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        String a=br.readLine(),b=br.readLine();
        if(a==null||b==null)return;
        System.out.println(check(a,b)||check(b,a)?"Yes":"No");
    }
}

