import sys

def check_palindrome_formation(a: str, b: str) -> bool:
    def is_palindrome(s, i, j):
        return s[i:j+1] == s[i:j+1][::-1]

    def check(s1, s2):
        i, j = 0, len(s1) - 1
        while i < j and s1[i] == s2[j]:
            i += 1
            j -= 1
        return is_palindrome(s1, i, j) or is_palindrome(s2, i, j)

    return check(a, b) or check(b, a)

def main():
