struct ListNode {
    int val;
    struct ListNode *next;
};

void reorderList(struct ListNode* head) {
    if (head == NULL || head->next == NULL || head->next->next == NULL) {
        return;
    }

    struct ListNode* second = head->next;
    struct ListNode* prevSecond = head;
    struct ListNode* ptr = head->next->next;

    while (ptr != NULL) {
        second->next = ptr->next;
        ptr->next = prevSecond->next;
        prevSecond->next = ptr;

        prevSecond = ptr;
        ptr = second->next;
    }

    head->next = prevSecond;
}

