struct ListNode {
  int val;
  ListNode *next;
  ListNode(int x) : val(x), next(NULL) {}
};

void reorderList(ListNode *head) {
    if (head == NULL || head->next == NULL || head->next->next == NULL) {
        return;
    }

    ListNode *slow = head, *fast = head->next;

    while(fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }

    ListNode *second = slow->next;
    slow->next = NULL;
    second->next = NULL;

    ListNode *prev = NULL, *curr = head, *nextTemp;

    while(curr != NULL) {
        nextTemp = curr->next;
        curr->next = prev;
        prev = curr;
        curr = nextTemp;
    }

    ListNode *l1 = prev, *l2 = second;

    while(l1 != NULL) {
        nextTemp = l2->next;
        l2->next = l1->next;
        l1->next = l2;
        l2 = l2->next->next;
        l1 = l1->next;
    }

    head = prev;
}

