    constructor(data) {
        this.data = data;
        this.next = null;
    }
}

class LinkedList {
    constructor() {
        this.head = null;
    }

    append(data) {
        let node = new Node(data);

        if (!this.head) {
            this.head = node;
        } else {
            let current = this.head;
            while (current.next) {
                current = current.next;
            }
            current.next = node;
        }
    }

    reorder() {
        if (!this.head || !this.head.next) {
            return;
        }

        let slow = this.head;
        let fast = this.head.next;

        while(fast && fast.next) {
            if(slow) {
                slow = slow.next;
            }
            fast = fast.next.next;
        }

        let second = slow.next;
        slow.next = null;

        second.next = this.head;

        this.head = second;
    }

    print() {
        let current = this.head;
        while (current) {
            console.log(current.data);
            current = current.next;
        }
    }
