int shortestSubarray(vector<int>& nums, int k) {
    int n = nums.size();
    deque<int> dq;
    int res = n + 1;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += nums[i];
        if (sum >= k) {
            res = min(res, i + 1);
        }
        while (!dq.empty() && sum - dq.front() >= k) {
            sum -= dq.front();
            dq.pop_front();
            if (res > i - dq.front()) {
                res = i - dq.front();
            }
        }
        if (sum >= k) {
            dq.clear();
        }
        dq.push_back(i);
    }
    if (res == n + 1) {
        return -1;
    }
    return res;
}

