  const cycle = numRows * 2 - 2;
  const ret = [];
  for (let i = 0; i < length; i += cycle) {
    ret.push(S[i]);
    if (i + numRows < length) ret.push(S[i + numRows]);
    if (i + numRows * 2 < length) ret.push(S[i + numRows * 2]);
  }
