static int feasible(const long long *pages, int n, int students, long long limit)
{
    int used = 1;
    long long current = 0;

    for (int i = 0; i < n; ++i) {
        if (pages[i] > limit) {
            return 0;
        }

        if (current + pages[i] <= limit) {
            current += pages[i];
        } else {
            ++used;
            current = pages[i];
        }
    }

    return used <= students;
}

