bool canAllocate(const vector<int>& books, int pages, int students) {
    int booksAllocated = 1;
    int pagesLeft = pages;

    for (int book : books) {
        if (book <= pagesLeft) {
            pagesLeft -= book;
        } else {
            booksAllocated++;
            pagesLeft = pages - book;
        }
    }

    return booksAllocated <= students;
}

