    vector<double> res(n, -1.0);
    stack<int> st;
    for (int i = n - 1; i >= 0; i--) {
        while (!st.empty()) {
            int j = st.top();
            if (cars[i].second <= cars[j].second) { st.pop(); continue; }
            double t = (double)(cars[j].first - cars[i].first) / (cars[i].second - cars[j].second);
            if (res[j] == -1.0 || t <= res[j]) { res[i] = t; break; }
