function uniquePaths(m, n) {

    let paths = new Array(m);
    for (let i = 0; i < m; i++) {
        paths[i] = new Array(n).fill(-1);
    }

    function calculatePaths(x, y) {

        if (x == m - 1 && y == n - 1) {
            return 1;
        }

        if (x >= m || y >= n) {
            return 0;
        }

        if (paths[x][y] != -1) {
            return paths[x][y];
        }

        paths[x][y] = calculatePaths(x + 1, y) + calculatePaths(x, y + 1);
        return paths[x][y];
    }

    return calculatePaths(0, 0);
}

