    let minSum = Number.MAX_SAFE_INTEGER;
    let currentSum = 0;

    for (let i = 0; i < N; i++) {
        currentSum += arr[i];

        if (i >= K - 1) {
            minSum = Math.min(minSum, currentSum);
            currentSum -= arr[i - (K - 1)];
        }
    }

    return minSum;
}

