#include <stdio.h>

int canPartition(int* nums, int numsSize, int k, int target) {
    if (numsSize < k) {
        return 0;
    }

    int sum = 0;
    for (int i = 0; i < numsSize; i++) {
        sum += nums[i];
    }

    if (sum % k != 0) {
        return 0;
    }

    target = sum / k;
    int* dp = (int*)malloc(sizeof(int) * (target + 1));
    memset(dp, 0, sizeof(int) * (target + 1));

    for (int i = 0; i < numsSize; i++) {
        for (int j = target; j >= nums[i]; j--) {
            dp[j] = dp[j] || dp[j - nums[i]];
        }
    }

    free(dp);

    for (int i = 1; i <= target; i++) {
        if (dp[i] == 0) {
            return 0;
        }
    }

    return 1;
}

