        if (total % k != 0 || n < k) { printf("false\n"); return 0; }
        int target = total / k;
        qsort(nums, n, sizeof(int), cmp);
        if (nums[0] > target) { printf("false\n"); return 0; }
        for (int i = 0; i < k; i++) subsets[i] = 0;
