bool bt(vector<int>& a, vector<int>& buckets, int idx, int target) {
    if (idx == (int)a.size()) { for (int b : buckets) if (b!=target) return false; return true; }
    set<int> seen;
    for (int i = 0; i < (int)buckets.size(); ++i) {
        if (seen.count(buckets[i])) continue;
        if (buckets[i]+a[idx] > target) continue;
        seen.insert(buckets[i]);
        buckets[i] += a[idx];
        if (bt(a, buckets, idx+1, target)) return true;
