    int maxLen = 0, l = 0;

    while (l < numsSize) {
        if (nums[l] % 2 == 0 && nums[l] <= threshold) {
            int r = l;
            while (r + 1 < numsSize && nums[r + 1] <= threshold && (nums[r] % 2) != (nums[r + 1] % 2)) {
