bool wordBreak(char *s, int n, char *dict[n]) {
    int len = strlen(s);
    bool dp[MAX_LENGTH+1] = {0};
    dp[0] = true;

    for (int i = 1; i <= len; i++) {
        for (int j = 0; j < n; j++) {
            if (dp[i-1] && strncmp(s, dict[j], i) == 0) {
                dp[i] = true;
                break;
            }
        }
    }

    return dp[len];
}

