int maxScore(int* nums, int numsSize, int K){
    int* dp = (int*)malloc(sizeof(int) * numsSize);
    dp[0] = nums[0];
    int max_val = nums[0];

    for(int i = 1; i < numsSize; i++){
        dp[i] = nums[i];
        for(int j = 1; j <= K; j++){
            if(i - j >= 0) dp[i] = max(dp[i], dp[i - j] + nums[i]);
            if(i - j - 1 >= 0) dp[i] = max(dp[i], dp[i - j - 1] + nums[i]);
        }
        max_val = max(max_val, dp[i]);
    }
    return max_val;
}

