ListNode* removeZeroSumSublists(ListNode* head) {
    ListNode dummy(0);
    dummy.next = head;
    int sum = 0;
    std::unordered_set<int> sumSet;
    while (head != nullptr) {
        sum += head->val;
        if (sum == 0) {
            head = head->next;
            continue;
        }
        if (sumSet.find(sum) != sumSet.end()) {
            ListNode* node = head;
            int tempSum = sum + node->val;
            while (tempSum != sum) {
                tempSum += node->next->val;
                node = node->next;
            }
            node->next = node->next->next;
        } else {
            sumSet.insert(sum);
        }
        head = head->next;
    }
    return dummy.next;
}

