struct Node {
  int data;
  struct Node* next;
};

int convertBinaryToDecimal(struct Node* head) {
  struct Node* temp = head;
  int result = 0;
  int power = 0;

  while (temp != NULL) {
    result += temp->data * pow(2, power);
    temp = temp->next;
    power++;
  }

  return result;
}

