        for (int j = 0; j < n; j++) {
            dp[n - 1][j] = matrix[n - 1][j];
        }
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                dp[i][j] = matrix[i][j] + Math.min(Math.min(j > 0 ? dp[i + 1][j - 1] : Integer.MAX_VALUE, dp[i + 1][j]),
