void add_edge(Graph* graph, int src, int dest) {
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->vertex = dest;
    temp->next = graph->adjacency_list[src];
    graph->adjacency_list[src] = temp;

    temp = (Node*)malloc(sizeof(Node));
    temp->vertex = src;
    temp->next = graph->adjacency_list[dest];
    graph->adjacency_list[dest] = temp;
}

