    int v;
    for (v = 0; v < graph->num_of_vertices; ++v) {
        Node* temp = graph->adjacency_list[v];
        printf("Adjacency list of vertex %d:\n", v);
        while (temp) {
            printf("%d ", temp->vertex);
            temp = temp->next;
        }
        printf("\n");
    }
}

