function readTree(separateValues = false) {
  const n = num();
  if (!Number.isFinite(n) || n <= 0) return { a: [], root: -1 };
  const a = Array.from({ length: n }, () => ({ v: 0, l: -1, r: -1 }));
  if (separateValues) {
    for (let i = 0; i < n; i++) a[i].v = num();
    for (let i = 0; i < n; i++) { a[i].l = num(); a[i].r = num(); }
  } else {
    for (let i = 0; i < n; i++) { a[i].v = num(); a[i].l = num(); a[i].r = num(); }
  }
  const indeg = new Int32Array(n);
  for (const x of a) {
    if (x.l >= 0 && x.l < n) indeg[x.l]++;
    if (x.r >= 0 && x.r < n) indeg[x.r]++;
  }
  let root = -1;
  for (let i = 0; i < n; i++) if (indeg[i] === 0) { root = i; break; }
  return { a, root };
}
