function bstInsert(t,x){if(t.root<0){t.a.push({v:x,l:-1,r:-1});t.root=0;return;}let u=t.root;while(true){if(x===t.a[u].v)return;if(x<t.a[u].v){if(t.a[u].l<0){t.a[u].l=t.a.length;t.a.push({v:x,l:-1,r:-1});return;}u=t.a[u].l;}else{if(t.a[u].r<0){t.a[u].r=t.a.length;t.a.push({v:x,l:-1,r:-1});return;}u=t.a[u].r;}}}
