const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim();
const tok = input ? input.split(/\s+/) : [];
let at = 0;
const next = () => tok[at++];
const num = () => Number(next());

function readTree(separateValues = false) {
  const n = num();
  if (!Number.isFinite(n) || n <= 0) return { a: [], root: -1 };
  const a = Array.from({ length: n }, () => ({ v: 0, l: -1, r: -1 }));
  if (separateValues) {
    for (let i = 0; i < n; i++) a[i].v = num();
    for (let i = 0; i < n; i++) { a[i].l = num(); a[i].r = num(); }
  } else {
    for (let i = 0; i < n; i++) { a[i].v = num(); a[i].l = num(); a[i].r = num(); }
  }
  const indeg = new Int32Array(n);
  for (const x of a) {
    if (x.l >= 0 && x.l < n) indeg[x.l]++;
    if (x.r >= 0 && x.r < n) indeg[x.r]++;
  }
  let root = -1;
  for (let i = 0; i < n; i++) if (indeg[i] === 0) { root = i; break; }
  return { a, root };
}
function printTree(t) {
  const out = [String(t.a.length)];
  for (const x of t.a) out.push(`${x.v} ${x.l} ${x.r}`);
  console.log(out.join('\n'));
}
function preorder(t) {
  const out=[]; if(t.root<0) return out; const st=[t.root];
  while(st.length){const u=st.pop();out.push(u);if(t.a[u].r>=0)st.push(t.a[u].r);if(t.a[u].l>=0)st.push(t.a[u].l);} return out;
}
function inorder(t) {
  const out=[],st=[]; let u=t.root;
  while(u>=0||st.length){while(u>=0){st.push(u);u=t.a[u].l;}u=st.pop();out.push(u);u=t.a[u].r;} return out;
}
function postorder(t) {
  const out=[],st=[]; if(t.root<0)return out; st.push([t.root,0]);
  while(st.length){const z=st[st.length-1],u=z[0]; if(z[1]===0){z[1]=1;if(t.a[u].l>=0)st.push([t.a[u].l,0]);}
    else if(z[1]===1){z[1]=2;if(t.a[u].r>=0)st.push([t.a[u].r,0]);}
    else{out.push(u);st.pop();}}
  return out;
}
function levels(t) {
  const ans=[]; if(t.root<0)return ans; let q=[t.root];
  while(q.length){ans.push(q);const nq=[];for(const u of q){if(t.a[u].l>=0)nq.push(t.a[u].l);if(t.a[u].r>=0)nq.push(t.a[u].r);}q=nq;}return ans;
}
function values(t, order=inorder) { return order(t).map(i=>t.a[i].v); }
function buildFromArray(arr) {
  const t={a:[],root:-1};
  const rec=(l,r)=>{if(l>r)return -1;const m=(l+r)>>1,id=t.a.length;t.a.push({v:arr[m],l:-1,r:-1});t.a[id].l=rec(l,m-1);t.a[id].r=rec(m+1,r);return id;};
  t.root=rec(0,arr.length-1);return t;
