    void findBridges(int n, vector<int> adj[], vector<pair<int, int>>& bridges) {
        int u, v, sz, cnt;
        vector<bool> visited(n + 1, false);
        vector<int> disc(n + 1, -1), low(n + 1, -1), parent(n + 1, -1);
        queue<int> q;

        for(u = 1; u <= n; u++) {
            if(!visited[u]) {
                dfs(u, adj, visited, disc, low, parent, bridges, q);
            }
        }

        while(!q.empty()) {
