        visited[u] = true;
        disc[u] = low[u] = ++cnt;
        q.push(u);

        for(auto v : adj[u]) {
            if(!visited[v]) {
                parent[v] = u;
                dfs(v, adj, visited, disc, low, parent, bridges, q);
                low[u] = min(low[u], low[v]);
