        }
        List<Integer>[] components = new List[N + 1];
        for (int i = 1; i <= N; i++) {
            components[i] = new ArrayList<>();
        }
        for (int i = 1; i <= N; i++) {
            if (components[i].isEmpty()) {
                dfs(i, i, graph, components);
            }
        }
        List<Integer> bridges = new ArrayList<>();
        for (int i = 1; i <= N; i++) {
            if (components[i].size() == 1) {
                bridges.add(i);
            }
        }
