        components[node].add(parent);
        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                if (components[neighbor].isEmpty()) {
                    dfs(neighbor, node, graph, components);
                }
                components[node].add(neighbor);
            }
        }
    }
}

