    while (head < tail) {
        int u = queue[head++];
        for (int v = 0; v < n; ++v) if (adj[u][v] && !seen[v]) { seen[v] = 1; queue[tail++] = v; }
    }
    int count = 0;
    for (int i = 0; i < n; ++i) count += seen[i];
