            stack[top++] = i;
            while(top > 0) {
                int u = stack[--top];
                if(!visited[u]) {
                    visited[u] = 1;
                    for(int v=0; v<n; v++) if(adj[u][v] && !visited[v]) stack[top++] = v;
                    order[idx++] = u;
                }
            }
        }
    }
    for(int i=0; i<n; i++) visited[i] = 0;
    int scc = 0;
    for(int i=n-1; i>=0; i--) {
        int u = order[i];
        if(!visited[u]) {
            int stack[n], top = 0;
            stack[top++] = u;
            while(top > 0) {
                int v = stack[--top];
                if(!visited[v]) {
                    visited[v] = 1;
                    for(int w=0; w<n; w++) if(radj[v][w] && !visited[w]) stack[top++] = w;
                }
            }
            scc++;
        }
    }
