class Edge {
public:
    int src, dest;
};

class Graph {
private:
    int V, E;
    vector<Edge> edges;
public:
    Graph(int V, int E);
    void addEdge(int src, int dest);
    int countSC();
};

Graph::Graph(int V, int E) {
    this->V = V;
    this->E = E;
}

void Graph::addEdge(int src, int dest) {
    edges.push_back(Edge{src, dest});
}

int find(vector<int> parent, int i) {
    if (parent[i] == i)
        return i;
    return find(parent, parent[i]);
}

void Union(vector<int> &parent, int x, int y) {
    parent[x] = y;
}

int Graph::countSC() {
    vector<int> parent;
    parent.resize(V);
    for (int i = 0; i < V; i++)
        parent[i] = i;

    for (int i = 0; i < E; i++) {
        int x = find(parent, edges[i].src);
        int y = find(parent, edges[i].dest);

        if (x != y)
            Union(parent, x, y);
    }

    int ans = 0;
    for (int i = 0; i < V; i++)
        if (parent[i] == i)
            ans++;

    return ans;
}

