bool isCycleUtil(int v, vector<int> graph[], bool visited[], bool *recStk) {
    visited[v] = true;
    recStk[v] = true;

    for (int u : graph[v]) {
        if (!visited[u]) {
            if (isCycleUtil(u, graph, visited, recStk)) {
                return true;
            } else if (recStk[u]) {
                return true;
