    recStk[v] = false;
    return false;
}

bool isCycle(int v, vector<int> graph[], int N) {
    bool visited[N] = {false};
    bool recStk[N] = {false};

    if (isCycleUtil(v, graph, visited, recStk)) {
        return true;
    }

    for (int i = 0; i < N; i++) {
        if (visited[i] && graph[i].size() > 0) {
            return false;
        }
    }

    return false;
}

