        visited[node] = true;
        if(visited.length === N + 1) {
            return true;
        }
        for(let neighbour of graph[node]) {
            if(!visited[neighbour]) {
                if(dfs(neighbour, visited)) {
                    return true;
                }
            }
        }
        visited[node] = false;
        return false;
