            for (size_t j = 0; j < minLen; j++) {
                if (w1[j] != w2[j]) {
                    if (!adj[w1[j]].count(w2[j])) {
                        adj[w1[j]].insert(w2[j]);
                        inDeg[w2[j]]++;
                    }
                    break;
                }
            }
        }
        std::queue<char> q;
        for (const auto& [c, deg] : inDeg) {
            if (deg == 0) q.push(c);
        }
        std::string res = "";
        while (!q.empty()) {
            char c = q.front();
            q.pop();
            res += c;
            for (char nxt : adj[c]) {
                if (--inDeg[nxt] == 0) q.push(nxt);
            }
        }
        return res.length() == inDeg.size() ? res : "";
    }
};

