int minEatingSpeed(int n, int piles[], int h) {
    long long total = 0;
    for (int i = 0; i < n; i++) {
        total += piles[i];
    }
    long long avg = total / n;
    long long remaining = total % n;
    if (remaining > 0) {
        avg++;
    }
    int l = 1;
    int r = avg;
    while (l < r) {
        int mid = (l + r) / 2;
        long long spent = 0;
        for (int i = 0; i < n; i++) {
            spent += piles[i] / mid;
            if (piles[i] % mid > 0) {
                spent++;
            }
        }
        if (spent > h) {
            l = mid + 1;
        } else {
            r = mid;
        }
    }
    return l;
}

