def minEatingSpeed(piles, h):
    def canEat(mid):
        return sum((p + mid - 1) // mid for p in piles) <= h

    left, right = 1, max(piles)
    while left < right:
        mid = (left + right) // 2
        if canEat(mid):
            right = mid
        else:
            left = mid + 1
    return left

