function findProvinces(matrix, N) {
  let provinces = 0;
  let visited = new Array(N).fill(false);

  for (let i = 0; i < N; i++) {
    if (!visited[i]) {
      visitProvince(matrix, visited, i);
      provinces++;
    }
  }

  return provinces;
}

