        while (i < n - 1 && nums[i] > nums[i + 1]) {
            const temp = nums[i];
            nums[i] = nums[i + 1];
            nums[i + 1] = temp;
            i++;
        }
    }
    const MOD = 1000000007n;
    let prod = 1n;
    for (const x of nums) {
        prod = (prod * BigInt(x)) % MOD;
    }
    console.log(prod.toString());
