            }
            if (swap || (count[res[i]-'a'][teams-1] == count[res[j]-'a'][teams-1] && res[i] > res[j])) {
                char t = res[i]; res[i] = res[j]; res[j] = t;
            }
        }
    }
    printf("%s\n", res);
