        for (int pos = 0; pos < m; ++pos) {
            int team = vote[pos] - 'A';
            if (team >= 0 && team < 26) {
                ++count[team][pos];
                present[team] = true;
            }
        }
    }

    std::vector<int> teams;
    for (int t = 0; t < 26; ++t) {
        if (present[t]) teams.push_back(t);
    }

