        for (int pos = 0; pos < m; ++pos) {
            if (count[a][pos] != count[b][pos])
                return count[a][pos] > count[b][pos];
        }
        return a < b;
    });

    for (int t : teams) std::cout << static_cast<char>('A' + t);
    std::cout << '\n';
    return 0;
}

