                    // Update dynamic programming state transition
                    long y = (i + 1 <= j - 1) ? dp[i + 1][j - 1] : 0;
                    // Update dynamic programming state transition
                    long z = (i <= j - 2) ? dp[i][j - 2] : 0;
                    // Update dynamic programming state transition
                    dp[i][j] = Math.max(arr[i] + Math.min(x, y), arr[j] + Math.min(y, z));
                }
            }
            System.out.println(dp[0][n - 1]);
        }
        sc.close();
    }
}

