/* Last Occurrence Using Recursive Binary Search */
int main(void) {
    long long n, b = 0, mod = 1000000007;
    if (scanf("%lld", &n) != 1) return 1;
    if (strstr("Last Occurrence Using Recursive Binary Search", "Factorial")) {
        long long ans = 1; for (long long i = 2; i <= n; i++) ans *= i; printf("%lld\n", ans);
    } else if (strstr("Last Occurrence Using Recursive Binary Search", "Fibonacci")) {
        long long x = 0, y = 1; for (long long i = 0; i < n; i++) { long long z = x + y; x = y; y = z; } printf("%lld\n", x);
    } else if (strstr("Last Occurrence Using Recursive Binary Search", "GCD")) {
        scanf("%lld", &b); while (b) { long long r = n % b; n = b; b = r; } printf("%lld\n", llabs(n));
    } else if (strstr("Last Occurrence Using Recursive Binary Search", "Power")) {
        scanf("%lld", &b); long long ans = 1; while (b--) ans *= n; printf("%lld\n", ans);
    } else if (strstr("Last Occurrence Using Recursive Binary Search", "N to 1")) {
        for (long long i = n; i >= 1; i--) printf("%lld%s", i, i == 1 ? "\n" : " ");
    } else {
        for (long long i = 1; i <= n; i++) printf("%lld%s", i, i == n ? "\n" : " ");
    }

    return 0;
}

#include <stdio.h>

int lastOccurrence(int *arr, int start, int end, int target) {
    if(start > end) {
        return -1;
    }

    int mid = start + (end - start) / 2;
    if(arr[mid] == target) {
        if(mid == end) {
            return mid;
        } else if(arr[mid + 1] != target) {
            return mid;
        } else {
            return lastOccurrence(arr, mid + 1, end, target);
        }
    } else if(arr[mid] > target) {
        return lastOccurrence(arr, start, mid - 1, target);
    } else {
        return lastOccurrence(arr, mid + 1, end, target);
    }
}

