using namespace std;

int lastOccurrence(const vector<long long>& a, int left, int right, long long target) {
    // On a match, continue right so the latest valid index is retained.
    if (left > right) return -1;
    int mid = left + (right - left) / 2;
    if (a[mid] == target) {
        int later = lastOccurrence(a, mid + 1, right, target);
        return later == -1 ? mid : later;
    }
    if (a[mid] < target) return lastOccurrence(a, mid + 1, right, target);
    return lastOccurrence(a, left, mid - 1, target);
}

