struct edge {
    int src, dest, weight;
};

struct graph {
    struct edge* edges;
    int nvertices, nedges;
    int* distances;
};

void init_graph(struct graph* g, int n, int m) {
    g->nvertices = n;
    g->nedges = m;
    g->distances = (int*)malloc(n * sizeof(int));
    for(int i = 0; i < n; i++) {
        g->distances[i] = INT_MAX;
    }
    g->edges = (struct edge*)malloc(m * sizeof(struct edge));
}

void add_edge(struct graph* g, int u, int v, int w) {
    g->edges[g->nedges].src = u;
    g->edges[g->nedges].dest = v;
    g->edges[g->nedges].weight = w;
    g->nedges++;
}

void bellman_ford(struct graph* g, int src) {
    g->distances[src] = 0;
    for(int i = 0; i < g->nvertices - 1; i++) {
        for(int j = 0; j < g->nedges; j++) {
            int u = g->edges[j].src;
            int v = g->edges[j].dest;
            int weight = g->edges[j].weight;
            if(g->distances[u] != INT_MAX && g->distances[u] + weight < g->distances[v]) {
                g->distances[v] = g->distances[u] + weight;
            }
        }
    }
    for(int j = 0; j < g->nedges; j++) {
        int u = g->edges[j].src;
        int v = g->edges[j].dest;
        int weight = g->edges[j].weight;
        if(g->distances[u] != INT_MAX && g->distances[u] + weight < g->distances[v]) {
            printf("Graph contains negative weight cycle\n");
            return;
        }
    }
}

int main() {
    int n, m, s;
    scanf("%d %d %d", &n, &m, &s);
    struct graph g;
    init_graph(&g, n, m);
    for(int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(&g, u, v, w);
    }
    bellman_ford(&g, s);
    for(int i = 0; i < n; i++) {
        if(g.distances[i] == INT_MAX) {
            printf("%d ", -1);
        } else {
            printf("%d ", g.distances[i]);
        }
    }
    return 0;
}

#include <stdio.h>
