void minHeapify(int arr[], int i, int k) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    if (left <= k && arr[left] < arr[smallest])
        smallest = left;

    if (right <= k && arr[right] < arr[smallest])
        smallest = right;

    if (smallest != i) {
        swap(&arr[i], &arr[smallest]);
        minHeapify(arr, smallest, k);
    }
}

void buildMinHeap(int arr[], int k) {
    for (int i = (k / 2) - 1; i >= 0; i--) {
        minHeapify(arr, i, k);
    }
}

void printArray(int arr[], int k) {
    for (int i = 0; i <= k; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

void heapSort(int arr[], int k) {
    buildMinHeap(arr, k);
    printArray(arr, k);
    for (int i = k; i > 0; i--) {
        swap(&arr[0], &arr[i]);
        printArray(arr, i);
        minHeapify(arr, 0, i);
    }
}

