            heap.push([arr[i], i]);
        }
        // Build Min Heap
        for (let i = Math.floor(k / 2) - 1; i >= 0; i--) {
            let idx = i;
            while (true) {
                let l = 2 * idx + 1, r = 2 * idx + 2, minIdx = idx;
                if (l < k && heap[l][0] < heap[minIdx][0]) minIdx = l;
                if (r < k && heap[r][0] < heap[minIdx][0]) minIdx = r;
                if (minIdx !== idx) {
                    [heap[idx], heap[minIdx]] = [heap[minIdx], heap[idx]];
                    idx = minIdx;
                } else break;
            }
        }
        
        function push(item) {
            heap.push(item);
            let i = heap.length - 1;
            while (i > 0) {
                let p = Math.floor((i - 1) / 2);
                if (heap[p][0] > heap[i][0]) {
                    [heap[p], heap[i]] = [heap[i], heap[p]];
                    i = p;
                } else break;
            }
        }
        function pop() {
            let top = heap[0];
            let last = heap.pop();
            if (heap.length > 0) {
                heap[0] = last;
                let i = 0;
                while (true) {
                    let l = 2 * i + 1, r = 2 * i + 2, minIdx = i;
                    if (l < heap.length && heap[l][0] < heap[minIdx][0]) minIdx = l;
                    if (r < heap.length && heap[r][0] < heap[minIdx][0]) minIdx = r;
                    if (minIdx !== i) {
                        [heap[i], heap[minIdx]] = [heap[minIdx], heap[i]];
                        i = minIdx;
                    } else break;
                }
            }
            return top;
        }
        
