#define N 1000
#define INF 100000000

int adj[N][N];
int dist[N][N];
int dx[8] = {-1, -1, -1, 1, 1, 1, 0, 0};
int dy[8] = {-1, 0, 1, -1, 0, 1, -1, 1};
int n;

typedef struct {
    int x, y, d;
} Node;

Node queue[N * N];
int head, tail;

void push(int x, int y, int d) {
    queue[tail++] = (Node){x, y, d};
}

Node pop() {
    return queue[head++];
}

int empty() {
    return head > tail;
}

void bfs(int sx, int sy) {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            dist[i][j] = INF;
        }
    }
    dist[sx][sy] = 0;
    push(sx, sy, 0);
    while (!empty()) {
        Node node = pop();
        int x = node.x, y = node.y, d = node.d;
        if (d < dist[x][y]) continue;
        for (int i = 0; i < 8; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (nx < 0 || ny < 0 || nx >= n || ny >= n || dist[nx][ny] <= d + 1) continue;
            if (adj[nx][ny] == 0 || dist[nx][ny] <= d + 1) {
                dist[nx][ny] = d + 1;
                push(nx, ny, d + 1);
            }
        }
    }
}

