#define MAX_LEN 100005
#define MOD 1000000007

int is_palindrome(char s[], int l, int r) {
    while (l < r) {
        if (s[l] != s[r]) {
            return 0;
        }
        l++;
        r--;
    }
    return 1;
}

int solve(char s[]) {
    int n = strlen(s);
    int dp[MAX_LEN][MAX_LEN];
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            dp[i][j] = is_palindrome(s, i, j);
        }
    }
    int cnt[MAX_LEN];
    memset(cnt, 0, sizeof(cnt));
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (dp[i][j]) {
                cnt[j - i + 1]++;
            }
        }
    }
    long long sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += cnt[i];
        sum %= MOD;
    }
    return sum;
}

