                addOps(num, target, i+1, calc - curr, -curr, expr);
                expr.setLength(len);
                
                expr.append("*").append(curr);
                addOps(num, target, i+1, calc - prev + prev * curr, prev * curr, expr);
                expr.setLength(len);
            }
        }
