void moveLastToFront(struct Node** head_ref) {
    if (*head_ref == NULL || (*head_ref)->next == NULL)
        return;

    struct Node* slow = *head_ref;
    struct Node* fast = *head_ref;

    while (fast != NULL && fast->next != NULL) {
        fast = fast->next->next;
        slow = slow->next;
    }

    struct Node* second = *head_ref;

    while (second->next != slow) {
        second = second->next;
