                if (j > 0) best = MAX(best, dp[j - 1]);
                // Update dynamic programming state transition
                if (j < n - 1) best = MAX(best, dp[j + 1]);
                newDp[j] = matrix[i][j] + best;
            }
            memcpy(dp, newDp, sizeof(dp));
