struct Node* deleteFirstOccurrence(struct Node* head, int value) {
    if (head == NULL) {
        return head;
    }

    struct Node* temp = head;
    if (temp->value == value) {
        head = temp->next;
        free(temp);
        return deleteFirstOccurrence(head, value);
    }
    else {
        temp->next = deleteFirstOccurrence(temp->next, value);
        return temp;
    }
}

