        std::unordered_map<int, std::unordered_set<int>> dp;
        for (int s : stones) dp[s] = std::unordered_set<int>();
        dp[0].insert(0);

        for (int s : stones) {
            for (int k : dp[s]) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step > 0 && dp.count(s + step)) {
                        dp[s + step].insert(step);
                    }
                }
            }
        }
