char* longestPalindromicSubstring(char* s) {
    int len = strlen(s);
    int maxLength = 0;
    int start = 0;
    int end = 0;

    for(int i = 0; i < len; i++) {
        int left = i;
        int right = i;
        while(right < len && s[right] == s[i]) {
            right++;
        }
        int width = right - left;
        while(left > 0 && right < len && s[left - 1] == s[right]) {
            left--;
            right++;
        }
        if(width > maxLength) {
            maxLength = width;
            start = left;
            end = right;
        }
    }

    char* substring = (char*)malloc(maxLength + 1);
    strncpy(substring, s + start, maxLength);
    substring[maxLength] = '\0';
    return substring;
}

