def longest_palindrome(s):
    def helper(s, l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]

    longest = ''
    for i in range(len(s)):
        palindrome = helper(s, i, i)
        if len(palindrome) > len(longest):
            longest = palindrome
        palindrome = helper(s, i, i+1)
        if len(palindrome) > len(longest):
            longest = palindrome
    return longest

