int top;

void push(int x) {
    if (top < MAXN) {
        stack[++top] = x;
    }
}

int pop() {
    return stack[top--];
}

long long getProduct(int k) {
    long long product = 1;
    for (int i = 1; i <= k; i++) {
        product *= stack[i];
    }
    return product;
}

