using namespace std;

class ProductOfNumbers {
public:
    deque<int> d;

    void add(int num) {
        d.push_back(num);
    }

    int getProduct(int k) {
        long long prod = 1;
        for (int i = 0; i < k; i++) {
            prod *= d[i];
        }
        for (size_t i = d.size(); i < d.size() + k; i++) {
            prod /= d[i - k];
            prod *= d[i];
        }
        return prod;
    }
};

