import java.io.*;
import java.util.*;

public class Main {
    private Deque<Integer> deque;
    private long product;
    private int K;

    public Main(int K) {
        this.K = K;
        deque = new ArrayDeque<>();
        product = 1;
    }

    public void add(int num) {
        deque.addLast(num);
        product *= num;
        if (deque.size() > K) {
            int removed = deque.removeFirst();
            product /= removed;
        }
    }

    public long getProduct() {
        return deque.size() == K ? product : -1;
    }

