class ProductOfNumbers:
    def __init__(self):
        self.stack = []
        self.product = 1

    def add(self, num: int) -> None:
        if num != 0:
            self.product *= num
            self.stack.append(self.product)

    def getProduct(self, k: int) -> int:
        if k >= len(self.stack):
            return self.product
        else:
            return self.stack[-1] // self.stack[len(self.stack) - k - 1]

