int damerau_levenshtein_distance(const string &a,const string &b){
    //unordered_map<int,int> da;
    //unordered_map<int,map<int,int>> d;
    vector<int> da_(26);
    vector<vector<int>> d_(a.size()+2,vector<int>(b.size()+2));
    auto da=[&](int i)->int&{
        return da_[i-'a'];
    };
    auto d=[&](int i,int j)->int&{
        return d_[i+1][j+1];
    };
    int maxdist=a.size()+b.size();
    d(-1,-1)=maxdist;
    for(int i=0; i<=a.size(); ++i){
        d(i,-1)=maxdist;
        d(i,0)=i;
    }
    for(int i=0; i<=b.size(); ++i){
        d(-1,i)=maxdist;
        d(0,i)=i;
    }
    for(int i=1; i<=a.size(); ++i){
        int db=0;
        for(int j=1; j<=b.size(); ++j){
            int k=da(b[j-1]),l=db,cost;
            if(a[i-1]==b[j-1]){
                cost=0;
                db=j;
            }else cost=1;
            d(i,j)=min({d(i-1,j-1)+cost,d(i,j-1)+1,d(i-1,j)+1,d(k-1,l-1)+(i-k-1)+1+(j-l-1)});
        }
        da(a[i-1])=i;
    }
    return d(a.size(),b.size());
}

