struct Range {
  int l, r, v;
  
  Range(int a = 0, int b = 0, int c = 0) {
    l = a, r = b, v = c;
  }
};

int main() {
  ios::sync_with_stdio(0);cin.tie(0);
  int n;
  std::cin >> n;
  std::vector<int> b(n);
  for(int i = 0; i < n; i++) {
    std::cin >> b[i];
  }
  auto check = [&](int x) {
    std::vector<Range> a;
    a.emplace_back(0, 1, x);
    for(auto p : b) {
      while(a.back().l > p) a.pop_back();
      if(a.back().r <= p) {
        assert(a.back().l <= p);
        a.emplace_back(a.back().r, p + 1, 1);
      } else {
        while(!a.empty() && a.back().v >= x) a.pop_back();
        if(a.empty()) return false;
        if(a.back().r > p) {
          a.back().r = p;
          int v = a.back().v + 1;
          assert(v <= x);
          if(a.back().l == a.back().r) a.pop_back();
          a.emplace_back(p, p + 1, v);
        } else {
          int v = a.back().v + 1;
          int r = a.back().r;
          a.back().r--;
          if(a.back().l == a.back().r) a.pop_back();
          assert(v <= x);
          a.emplace_back(r - 1, r, v);
          if(a.back().r <= p) a.emplace_back(a.back().r, p + 1, 1);
        }
      }
      assert(a.back().r == p + 1);
    }
    return true;
  };
  int l = 1, r = (int) 1e9;
  while(l != r) {
    int mid = (l + r) / 2;
    if(check(mid)) r = mid;
    else l = mid + 1;
  }
  std::cout << l << '\n';
  return 0;
}

