void upd(ll x){
    if(!x)return;
    t[x] = t[2 * x] + t[2 * x + 1];
    upd(x / 2);
}
ll cnt(ll x,ll L,ll R){
    if(L > r || R < l)return 0LL;
    if(L >= l && R <= r)return t[x];
    ll k1 = cnt(2 * x,L,(L + R)/2);
    ll k2 = cnt(2 * x + 1,(L+R)/2+1,R);
    return k1+k2;
}
