class Main {
    static int deno[] = {1, 2, 5, 10, 20, 50, 100, 200, 500, 2000};
    static int n = deno.length;

    public static int findMin(int V)
    {
        Vector<Integer> ans = new Vector<>();
        for (int i = n - 1; i >= 0; i--)
        {
            while (V >= deno[i])
            {
                V -= deno[i];
                ans.add(deno[i]);
            }
        }
        return ans.size();
    }
