struct Dinic {
	struct edge{int to;long long cap,rev;};
	vector<vector<edge>> G;
	vector<int> level;
	vector<int> iter;

	Dinic(int n):G(n, vector<edge>()),level(n),iter(n){}

	void add_edge(int from,int to,long long cap){
		G[from].push_back((edge){to,cap,(ll)G[to].size()});
		G[to].push_back((edge){from,0,(ll)G[from].size()-1});
	}

	void bfs(int s){
		fill(level.begin(), level.end(), -1);
		queue<int> que;
		level[s] = 0;
		que.push(s);
		while(!que.empty())	{
			int v = que.front();que.pop();
			for(int i = 0;i < G[v].size();++i){
				edge &e = G[v][i];
				if(e.cap > 0 && level[e.to] < 0){
					level[e.to] = level[v] + 1;
					que.push(e.to);
				}
			}
		}
	}

	int dfs(int v ,int t,long long f){
		if(v == t)return f;
		for(int &i = iter[v];i < G[v].size() ;++i){
			edge &e = G[v][i];
			if(e.cap > 0 && level[v] < level[e.to]){
				long long d = dfs(e.to,t,min(f,e.cap));
				if(d > 0){
					e.cap -= d;
					G[e.to][e.rev].cap += d;
					return d;
				}
			}
		}
		return 0;
	}

	long long solve(int s,int t){
		long long flow = 0;
		while(1){
			bfs(s);
			if(level[t] < 0)return flow;
			fill(iter.begin(), iter.end(), 0);
			long long f;while((f = dfs(s,t,INF)) > 0)flow += f;
		}
	}
};

int getCount(int h, int w, vector<vector<char>> &mp){
	if(h < 0 || w < 0 || h + 1 >= mp.size() || w + 1 >= mp[0].size()) {
		return -1;
	}

	int cou = 0;
	if(mp[h][w] == '#')cou++;
	if(mp[h+1][w] == '#')cou++;
	if(mp[h][w+1] == '#')cou++;
	if(mp[h+1][w+1] == '#')cou++;
	return cou;
}

P searchPairTate(int h, int w, vector<vector<char>> &mp){
	while(1) {
		h++;
		if(mp[h][w] != '#' || mp[h][w+1] != '#'){
			return MP(-1, -1);
		}
		if(getCount(h, w, mp) != 4) {
			break;
		}
	}
	if(getCount(h, w, mp) == 3){
		return MP(h, w);
	}
	else {
		return MP(-1, -1);
	}
}

P searchPairYoko(int h, int w, vector<vector<char>> &mp){
