		w++;
		if(mp[h][w] != '#' || mp[h+1][w] != '#'){
			return MP(-1, -1);
		}
		if(getCount(h, w, mp) != 4) {
			break;
		}
	}
	if(getCount(h, w, mp) == 3){
		return MP(h, w);
	}
	else {
		return MP(-1, -1);
	}
}

bool intersect(pair<P, P> a, pair<P, P> b){
	if(b.FI.SE < a.FI.SE || b.FI.SE > a.SE.SE){
		return false;
	}
	if(a.FI.FI < b.FI.FI || a.FI.FI > b.SE.FI){
		return false;
	}
	return true;
}

void sovle(int h, int w){
	vector<vector<char>> mp(h, vector<char>(w));
	vector<pair<P, P>> tate;
	vector<pair<P, P>> yoko;
	int corner = 0;

	REP(i, h){
		REP(j, w){
			cin >> mp[i][j];
		}
	}

	REP(i, h-1){
		REP(j, w-1){
			int cou = getCount(i, j, mp);
			if(cou == 3){
				corner++;
				P aite = searchPairTate(i, j, mp);
				if(aite.FI != -1){
					tate.EB(MP(i, j), MP(aite.FI, aite.SE));
				}
				aite = searchPairYoko(i, j, mp);
				if(aite.FI != -1){
					yoko.EB(MP(i, j), MP(aite.FI, aite.SE));
				}
			}
		}
	}

	vector<vector<int>> v(tate.size() + yoko.size() + 2);
	Dinic dinic(tate.size() + yoko.size() + 2);
	int start = tate.size() + yoko.size();
	int goal = tate.size() + yoko.size() + 1;

	REP(i, tate.size()){
		dinic.add_edge(start, i, 1);
		REP(j, yoko.size()) {
			if(intersect(yoko[j], tate[i])) {
				dinic.add_edge(i, j + tate.size(), 1);
			}
		}
	}
	REP(i, yoko.size()){
		dinic.add_edge(i + tate.size(), goal, 1);
	}

	cout << corner - (tate.size() + yoko.size() - dinic.solve(start, goal)) + 1 << endl;
}

