  int64_t sum = 0;
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
    a[i] -= 1 + i;
    sum += a[i];
  }
  sort(a.begin(), a.end());
  int64_t mid = a[n/2];
  uint64_t result = ~0LLU;
  for (int i = -2; i <= 2; ++i) {
    result = min(result, score(a, a[n/2+i]));
  }
  cout << result << "\n";
}

