#include <stdio.h>
#include <stdlib.h>
#define MAX_BUCKETS 10
typedef int TYPE;
typedef struct node_st { 
	TYPE inf;
	struct node_st *pnext;
} NODE;
typedef struct queue_st {
	NODE *pbegin, *pend;
} QUEUE;

void init_queue(QUEUE *);
NODE *make_node(TYPE);
void inqueue(QUEUE *, TYPE );
TYPE dequeue(QUEUE *);
int is_empty(QUEUE);

int find_max_significant(TYPE [], int);
