        cin >> h >> w;
        if(h == 0)
            return 0;

        wall.assign(2*h+1, vector<bool>(2*w+1, false));
        for(int i=0; i<2*h+1; ++i)
            wall[i][0] = wall[i][2*w] = true;
        for(int i=0; i<2*w+1; ++i)
            wall[0][i] = wall[2*h][i] = true;

        for(int i=0; i<h; ++i){
