            circuits[name] = {'weight': int(weight)}
            if children:
                circuits[name]['children'] = children.split(', ')

    print('Solution of Day 7 Part One: {0}'.format(recursive_circus_v1(circuits)))
    recursive_circus_v2(circuits)

