#include <bits/stdc++.h>
#define forn(i, n) for(ll i = 0; i < (ll)(n); i++)
typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;
typedef unsigned int ui32;
const long long INFLL = 1e18;
using namespace std;

const ll MAXN = 102 + 10;
const ll INF = 1000 * 1000 * 1000;

struct edge {
    ll a, b, cap, flow;
};

ll n, s, t, d[MAXN], ptr[MAXN], q[MAXN], a[MAXN];
vector<edge> e;
vector<ll> g[MAXN];

void add_edge (ll a, ll b, ll cap) {
    edge e1 = { a, b, cap, 0 };
    edge e2 = { b, a, 0, 0 };
    g[a].push_back ((ll) e.size());
    e.push_back (e1);
    g[b].push_back ((ll) e.size());
    e.push_back (e2);
}

bool bfs() {
    ll qh=0, qt=0;
    q[qt++] = s;
    memset (d, -1, n * sizeof d[0]);
    d[s] = 0;
    while (qh < qt && d[t] == -1) {
        ll v = q[qh++];
        for (size_t i=0; i<g[v].size(); ++i) {
            ll id = g[v][i],
                    to = e[id].b;
            if (d[to] == -1 && e[id].flow < e[id].cap) {
                q[qt++] = to;
                d[to] = d[v] + 1;
            }
        }
    }
    return d[t] != -1;
}

ll dfs (ll v, ll flow) {
    if (!flow)  return 0;
    if (v == t)  return flow;
    for (; ptr[v]<(ll)g[v].size(); ++ptr[v]) {
        ll id = g[v][ptr[v]],
                to = e[id].b;
        if (d[to] != d[v] + 1)  continue;
        ll pushed = dfs (to, min (flow, e[id].cap - e[id].flow));
        if (pushed) {
            e[id].flow += pushed;
            e[id^1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

ll dinic() {
    ll flow = 0;
    for (;;) {
        if (!bfs())  break;
        memset (ptr, 0, n * sizeof ptr[0]);
        while (ll pushed = dfs (s, INFLL))
            flow += pushed;
    }
    return flow;
}

int main() {
    //ios_base::sync_with_stdio(false);
    //cin.tie(0);
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout

    cin >> n;
    s = 0, t = n + 1;
    ll sum = 0;
    for (ll i = 1; i <= n; i++) {
        scanf("%lld", &a[i]);
        if (a[i] < 0) {
            add_edge(s, i, -a[i]);
        } else {
            sum += a[i];
            add_edge(i, t, a[i]);
        }
        for (int j = i + i; j <= n; j += i) {
            add_edge(i, j, INF * MAXN);
        }
    }
    n += 2;
    cout << max(0LL, sum - dinic()) << "\n";
    return 0;
}

