bool qry(int x){
	int num = x % X;
	int num_complete = x / X;
	
	if (num_complete >= N) return 1;
	int ans = 0;
	
	vi firstK;
	int sm = 0;
	FOR(i,0,num_complete-1){
		firstK.pb(vect[i].s);
		sm += vect[i].f;
	}
	ans = max(ans,sm);
	mem(vis,0);
	FOR(i,0,firstK.size() - 1){
		vis[vect[i].s] = 1;

		int res = 0;
		res += sm - vect[i].f + vect[num_complete].f;
		
		int idx = vect[i].s;
		if (num > B[idx]) res += B[idx] * L[idx] + (num - B[idx]) * U[idx];
		else res += num * L[idx];
		ans = max(ans,res);
	}

	FOR(i,0,N-1){
		if (vis[i]) continue;
		int res = 0;
		
		res += sm;
			
		if (num > B[i]) res += B[i] * L[i] + (num - B[i]) * U[i];
		else res += num * L[i];
		ans = max(ans,res);
	}
	return (ans >= tar);
}
