  rep(i,n){
    REP(j,i+1,n){
      if (node[i] == node[j])return false;
      if (isicpc[i] != isicpc[j] &&
	  edge[node[i]][node[j]])return false;
    }
  }
  return true;
}

void state::makest(){
  st=lastmove;
  rep(i,n){
    st=st*18 + node[i];
  }
}

int bfs(int n,state ini,vector<P> &node,int ma){
  queue<state> Q;  
  set<ull> S;
  ini.lastmove=icpc;
  ini.makest();
  Q.push(ini);
  S.insert(ini.st);
  ini.lastmove=acm;
  ini.makest();
  Q.push(ini);
  S.insert(ini.st);
  if (ini.isclear())return 0;

  while(!Q.empty()){
    state now = Q.front();Q.pop();
    int curmove=now.lastmove==icpc?acm:icpc;
    rep(i,now.n){
      if (curmove==icpc && !isicpc[i])continue;
      if (curmove==acm  && isicpc[i])continue;
      rep(j,n){
	if (!edge[now.node[i]][j])continue;
	state next = now;
	next.cnt++;
	next.lastmove=curmove;
	next.node[i]=j;
	if  (!next.isvalid(i,now.node[i],node))continue;
	sort(next.node,next.node+ma);
	sort(next.node+ma,next.node+next.n);
	next.makest();
	if (S.find(next.st) == S.end()){
	  if (next.isclear()){
	    return next.cnt;
	  }
	  S.insert(next.st);
	  Q.push(next);
	}
      }
    }    
  }
  return -1;
}

int getindex(P &a,map<P,int> &M){
  int index = M.size();
  if (M.find(a) == M.end())M[a]=index;
  return M[a];
}

void make_intersection(vector<Line> ver,vector<Line>hor, map<P,int> &M){
  rep(i,ver.size()){
    rep(j,hor.size()){
      if (ver[i].first.imag()  <= hor[j].first.imag() &&
	  ver[i].second.imag() >= hor[j].first.imag() &&
	  hor[j].first.real()  <= ver[i].first.real() &&
	  hor[j].second.real() >= ver[i].first.real()){
	P ins(ver[i].first.real(),hor[j].first.imag());
	getindex(ins,M);
      }
    }
  }
}

void make_graph(vector<P> node,vector<Line> ver,
		map<P,int> M){
  rep(i,ver.size()){
