long long size[31]{ 1 };

long long rec(long long, long long, long long, long long, long long, bool);
long long sq(long long a, long long b, long long c, long long d, long long s) {
	s /= 3;
	long long aa = a / s;
	long long bb = b / s;
	long long cc = c / s;
	long long dd = d / s;
	if (bb == dd) {
		swap(a, b);
		swap(c, d);
		swap(aa, bb);
		swap(cc, dd);
	}
	if (aa != cc)return abs_(a - c) + abs_(b - d);
	if (bb == dd) return sq(a % s, b % s, c % s, d % s, s);
	return rec(a % s, b, c % s, d, s, aa == 1);
}

long long rec(long long a, long long b, long long c, long long d, long long w, bool bl) {
	if (!bl) {
		if (w == 1)return abs_(a - c) + abs_(b - d);
		w /= 3;
		long long aa = a / w;
		long long cc = c / w;
		if (aa == cc)return rec(a % w, b, c % w, d, w, aa == 1);
		return abs_(a - c) + abs_(b - d);
	}
	else {
		if (abs_((b / w) - (d / w)) == 1)return rec(a, b, c, d, w, false);
		return abs_(b - d) + minimum(a + c + 2, 2 * w - a - c);
	}
}

