void swap(int *a, int *b) {
    int c = *a;
    *a = *b;
    *b = c;
}

void merge(int l, int r) {
    int mid = (l + r) >> 1;	
    // 两端的开始和结束
    int i = l, j = mid + 1; 
    int k = l;
    while((i <= mid) || (j <= r)) {	// 合并
        if(j > r || (i <= mid && a[i] <= a[j])) {
            // 如果右子列空了或者左子列当前元素小于右子列当前元素，新的位是左面第一位，且计算逆序对数
            tem[k++] = a[i++];
        }
        else {// 否则，新的位是右面第一位
            tem[k++] = a[j++];
        }
    }
    
    for(int i = l;i <= r;i++) 
        a[i] = tem[i];    // 归还排好序的段
}

void mergeSort(int l, int r) {
    int mid = (l + r) >> 1;
    if(l < r) {
        // 先对前后两部分排序
        mergeSort(l, mid);
        mergeSort(mid + 1, r);
        // 合并两个有序数组
        merge(l, r);
    }
}

