int calc(int s,int t,int n){
	rep(i,n)dist[i]=INF;
	dist[s]=0;
	pq.push(mp(0,s));
	while(!pq.empty()){
		pii x=pq.top();
		pq.pop();
		x.fst=-x.fst;
		if(dist[x.snd]!=x.fst)continue;
		rep(i,edge[x.snd].size()){
			pii y=edge[x.snd][i];
			if(dist[y.fst]>dist[x.snd]+y.snd){
				dist[y.fst]=dist[x.snd]+y.snd;
				pq.push(mp(-dist[y.fst],y.fst));
			} 
		}
	}
	if(dist[t]==INF)return -1;
	return dist[t];
}

