// Find the maximum profit you can achieve. You may complete as many transactions as you like (i.e., buy one and sell one share of the stock multiple times) with the following restrictions:

// After you sell your stock, you cannot buy stock on the next day (i.e., cooldown one day).
// Note: You may not engage in multiple transactions simultaneously (i.e., you must sell the stock before you buy again).



// Example 1:

// Input: prices = [1,2,3,0,2]
// Output: 3
// Explanation: transactions = [buy, sell, cooldown, buy, sell]
// Example 2:

// Input: prices = [1]
// Output: 0


// Constraints:

// 1 <= prices.length <= 5000
// 0 <= prices[i] <= 1000


/**
 * @param {number[]} prices
 * @return {number}
 */
 var maxProfit = function(prices) {
    let dp = {}

    function dfs(i, buying){
        if(i >= prices.length){
            return 0
        }
        if([i, buying].toString() in dp ){
            return dp[[i, buying].toString()] 
        }
          let cooldownProfit= dfs(i+1, buying)
        if(buying){
            let buyProfit = dfs(i+1, !buying) - prices[i]
            dp [[i, buying].toString()] = Math.max(buyProfit,cooldownProfit)
        }
        else{
             let sellProfit = dfs(i+2, !buying) + prices[i]
             dp [[i, buying].toString()] = Math.max(sellProfit,cooldownProfit)
        }
        return dp[[i, buying].toString()]
    }

    return dfs(0, true)
};

