#define MAXSIZE 5

struct SimpleArrayStack {
    int top;
    int capacity;
    int *array;
};

struct SimpleArrayStack *CreateStack(){
    struct SimpleArrayStack *S = malloc(sizeof(struct SimpleArrayStack));  
    if(!S) 
     return NULL;
    S->capacity = MAXSIZE;
    S->top = -1;
    S->array = malloc(S->capacity * sizeof(int));	// allocate an array of size 1 initially

    if(!S->array) 
        return NULL;
    return S;
}

int IsFullStack(struct SimpleArrayStack *S){
    return (S->top == S->capacity-1);
}

void Push(struct SimpleArrayStack *S, int x){
    // No overflow in this implementation
    if(IsFullStack(S)){   
        printf("Overflow: Stack full");
        return;
   }
    S->array[++S->top] = x;
}

int IsEmptyStack(struct SimpleArrayStack *S){
    return S->top == -1;
}

int Top(struct SimpleArrayStack *S){
    if(IsEmptyStack(S))     
     return INT_MIN;

    return S->array[S->top];
}

int Pop(struct SimpleArrayStack *S){
    if(IsEmptyStack(S)){  
        printf("Underflow: Stack empty");
        return INT_MIN;
    }
    return S->array[S->top--];
}

void DeleteStack(struct SimpleArrayStack *S){
    if(S) {
        if(S->array) 
            free(S->array);
        free(S);
    }
}

void testSimpleArrayStack(){
    struct SimpleArrayStack *s = CreateStack();
    Push(s, 10);
    Push(s, 1);
    Push(s, 11);
    Push(s, 2);
    Push(s, 10);
    Push(s, 50);
    while(!IsEmptyStack(s)){
        printf("%d\n", Pop(s));
    }
    DeleteStack(s);
}

// Adjascency List representation in C

#include <stdio.h>
#include <stdlib.h>

struct node
{
    int vertex;
    struct node *next;
};
struct node *createNode(int);

struct Graph
{
    int numVertices;
    struct node **adjLists;
};

// Create a node
struct node *createNode(int v)
{
    struct node *newNode = malloc(sizeof(struct node));
    newNode->vertex = v;
    newNode->next = NULL;
    return newNode;
}

// Create a graph
struct Graph *createAGraph(int vertices)
{
    struct Graph *graph = malloc(sizeof(struct Graph));
    graph->numVertices = vertices;

    graph->adjLists = malloc(vertices * sizeof(struct node *));

    int i;
    for (i = 0; i < vertices; i++)
        graph->adjLists[i] = NULL;

    return graph;
}

// Add edge
void addEdge(struct Graph *graph, int s, int d)
{
    // Add edge from s to d
    struct node *newNode = createNode(d);
    newNode->next = graph->adjLists[s];
    graph->adjLists[s] = newNode;

    // Add edge from d to s
    newNode = createNode(s);
    newNode->next = graph->adjLists[d];
    graph->adjLists[d] = newNode;
}

// Print the graph
void printGraph(struct Graph *graph)
{
    int v;
    for (v = 0; v < graph->numVertices; v++)
    {
        struct node *temp = graph->adjLists[v];
        printf("\n Vertex %d\n: ", v);
        while (temp)
        {
            printf("%d -> ", temp->vertex);
            temp = temp->next;
        }
        printf("\n");
    }
}

int main()
{
    struct Graph *graph = createAGraph(4);
    addEdge(graph, 0, 1);
    addEdge(graph, 0, 2);
    addEdge(graph, 0, 3);
    addEdge(graph, 1, 2);

    printGraph(graph);

    return 0;
}

