void Edmonds_Karp(int s, int t)
{
	bool has_ap = false;
	do
	{
		has_ap = false;
		for (int i = 1; i < 10000; i++)
		{
			V[i].inq = false;
		}
		hp = tp = 0;
		enqueue(s);
		V[s].inq = true;
		while (hp != tp)
		{
			int u = dequeue();
			if (u == t)
			{
				int x = u, apflow = INF;
				while (x != s)
				{
					if (E[V[x].pree].flow < apflow)
					{
						apflow = E[V[x].pree].flow;
					}
					x = V[x].prev;
				}
				ans += apflow;
				x = u;
				while (x != s)
				{
					E[V[x].pree].flow -= apflow;
					E[V[x].pree ^ 1].flow += apflow;
					x = V[x].prev;
				}
				has_ap = true;
				break;
			}
			for (int cur = V[u].first; cur != 0; cur = E[cur].next)
			{
				if (V[E[cur].endp].inq == false && E[cur].flow > 0)
				{
					enqueue(E[cur].endp);
					V[E[cur].endp].inq = true;
					V[E[cur].endp].prev = u;
					V[E[cur].endp].pree = cur;
				}
			}
		}
	} while (has_ap == true);
}

