typedef long long lol;
typedef unsigned long long ull;
typedef __uint128_t bll;
struct FastMod {
	ull b, m;
	FastMod(ull b) : b(b), m(ull((bll(1) << 64) / b)) {}
	ull mod(ull a) {
		ull q = (ull)((bll(m) * a) >> 64);
		ull r = a - q * b; 
		return r >= b ? r - b : r;
	}
};
FastMod F(2);

const int N = 2e2 + 5;
int _w;

int fac[N] , binom[N][N];
int n , k , mod;
inline int pls( int a , int b ) { a += b - mod; return a + ( a >> 31 & mod ); }
inline int mns( int a , int b ) { a -= b; return a + ( a >> 31 & mod ); }
inline void inc( int & a , int b ) { a += b - mod; a += a >> 31 & mod; }
inline void dec( int & a , int b ) { a -= b; a += a >> 31 & mod; }

int _solve( int n , int m , int k ) {
  static int f[N][N];
  memset( f , 0 , sizeof f );
  f[0][0] = 1;
  for( int i = 1 , s ; i <= m ; ++i ) {
    s = 0;
    for( int j = 0 ; j < n ; ++j ) {
      inc( s , f[j][i - 1] );
      if( (m-i+1)+(j-1) <= k && (n-j)+(i-1) <= k ) 
        f[j][i] = s;
      else f[j][i] = 0;
    }
  }
  int res = 0;
  for( int i = 1 ; i <= n ; ++i )
    inc( res , f[i][m] );
  return res;
}

int solve( int n , int k ) {
  if( n == 1 ) return 1;
  int res = 0;
  for( int i = 1 ; i - 1 <= k && i <= n ; ++i ) 
    inc( res , _solve( i , n - i , k ) );
  res = F.mod( (ull)res * fac[n - 1] );
  return res;
}

int main( void ) {
  _w = scanf("%d%d%d",&n,&k,&mod);
  F = FastMod( mod );
  fac[0] = fac[1] = 1;
  for( int i = 0 ; i <= n ; ++i ) {
    binom[i][0] = 1;
    for( int j = 1 ; j <= i ; ++j )
      binom[i][j] = pls( binom[i - 1][j] , binom[i - 1][j - 1] );
  }
  for( int i = 2 ; i <= n ; ++i )
    fac[i] = F.mod( (ull)fac[i - 1] * i );
  int ans = 0;
  for( int i = 0 ; i <= k ; ++i )
    ans = F.mod( F.mod( (ull)binom[n][i] * fac[i] ) * solve( n - i , k - i ) + ans );
  printf("%d",ans);
  return 0;
}

