#include <cstdio>
#include <cstring>
#include <algorithm>

const int N = 20, MOD = 1000000007;

int n, m, f[1 << N];

int mask[N][N];

bool init() {
  int k;
  scanf("%d%d%d", &n, &m, &k);
  --n;
  while (k--) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    mask[a - 1][b - 1] |= 1 << c;
  }
  for (int i = 0; i < m; ++i) if (std::count(mask[i], mask[i] + n, 3)) return false;
  return true;
}

void solve(int k) {
  int x = 0, y = 0;
  for (int i = 0; i < n; ++i) {
    if (mask[k][i] & 1) x |= 1 << i;
    if (mask[k][i] & 2) y |= 1 << i;
  }
  static int temp[1 << N];
  for (int i = 0; i < n; ++i) {
    memcpy(temp, f, sizeof temp);
    for (int s = 0; s < (1 << n); ++s) {
      if (!(s >> i & 1) || !f[s]) continue;
      int t = s ^ (1 << i);
      for (int j = i - 1; j >= 0; --j) if (t >> j & 1) break; else (temp[t | (1 << j)] += f[s]) %= MOD;
    }
    memcpy(f, temp, sizeof temp);
  }
  for (int i = 0; i < n; ++i) {
    memcpy(temp, f, sizeof temp);
    for (int s = 0; s < (1 << i); ++s) (temp[s | (1 << i)] += f[s]) %= MOD;
    memcpy(f, temp, sizeof temp);
  }
  for (int s = 0; s < (1 << n); ++s) if ((s & x) || (s & y) != y) f[s] = 0;
}

int main() {
  if (!init()) return puts("0"), 0;
  f[0] = 1;
  for (int i = 0; i < m; ++i) solve(i);
  int ans = 0;
  for (int s = 0; s < (1 << n); ++s) (ans += f[s]) %= MOD;
  printf("%d\n", (ans + MOD) % MOD);
  return 0;
}

