/*
 * Problem : Given a linked list, and two data values, x and y. 
 * Goal:     Swap the nodes of linkedlist by swapping pointers 
 *           (and not swapping data) such that nodes with data x will contain y and vice versa.
 *
 */


#include <iostream>


struct Node {
  int data;
  Node* next;
  Node(int d) : data{d}, next{nullptr} { }
};


/**** Algorithm Function ****/
void swapSpecial(Node* & head, int x, int y) {

  //empty list
  if (head == nullptr) {
    return;
  }

  //nothing to do if both are values are same.
  if ( x == y ) {
    return;
  }

  Node * prevx = nullptr;
  Node * currx = head;
  Node * prevy = nullptr;
  Node * curry = head;

  //search for x
  while ( currx && currx->data != x ) {
    prevx = currx;
    currx = currx->next;
  }
  //search for y
  while ( curry && curry->data != y ) {
    prevy = curry;
    curry = curry->next;
  }
  //x or y not found
  if ( currx == nullptr || curry == nullptr ) {
    return;
  }

  //if x is not head
  if ( prevx != nullptr ) {
    prevx->next = curry;
  } else {
    head = curry;
  }

  //similarly if y is not head
  if ( prevy != nullptr) {
    prevy->next = currx;
  } else {
    head = currx;
  }

  //now lets swap the next pointers
  Node *temp = curry->next;
  curry->next = currx->next;
  currx->next = temp;
}

void insert(Node* & head, int data) {
  if (head == nullptr) {
    head = new Node(data);
    return;
  }
  Node *temp = head;
  while(temp->next != nullptr) {
    temp = temp->next;
  }
  temp->next = new Node(data);
}

void printList(Node * head) {
  while (head) {
    std::cout << head->data << "-->";
    head = head->next;
  }
  std::cout << "null" << std::endl;
}

int main() {
  Node *head = nullptr;
  insert(head, 10);
  insert(head, 15);
  insert(head, 12);
  insert(head, 13);
  insert(head, 20);
  insert(head, 14);
  printList(head);
  std::cout << "Replacing 12 with 20 and 20 with 12:\n";
  swapSpecial(head, 12, 20);
  printList(head);

  return 0;
}

#include <cstdio>

#define MAX_N 10000000

typedef long long ll;

using namespace std;

// p must be a prime greater than n.
ll n, fac_inv[MAX_N], p;

ll qpow(ll x, ll y)
{
	if (y == 1) return x;
	ll t = qpow(x, y >> 1);
	t = t * t % p;
	if ((y & 1) == 0) return t;
	else return t * x % p;
}

ll fac(ll x)
{
	ll res = 1;
	for (int i = 2; i <= x; i++)
	{
		res = res * i % p;
	}
	return res;
}

void fac_inv_sieve()
{
	fac_inv[n] = qpow(fac(n), p - 2);
	for (ll i = n - 1; i >= 1; i--)
	{
		fac_inv[i] = fac_inv[i + 1] * (i + 1) % p;
	}
}

int main()
{
	scanf("%lld%lld", &n, &p);
	fac_inv_sieve();
	for (int i = 1; i <= n; i++)
	{
		printf("inv(fac(%d)) mod %lld = %lld\n", i, p, fac_inv[i]);
	}
	return 0;
}

""" 
    Dijkstra's algorithm
    
    Implementation of the straighforward solution of Dijkstra's algorithm to compute shortest path in 
    the given graph.
    
    In this particular exercise, the task is to find the shortest path from the first vertex to all other 
    vertices of the graph and then report the shortest path distance calculated for the nodes below:
    7, 37, 59, 82, 99, 115, 133, 165, 188, 197
"""

import sys
sys.path.append("..")
from utils.file_reader import *


def nodes_to_report():
    return [7, 37, 59, 82, 99, 115, 133, 165, 188, 197]


def get_data():
    g = {}
    vertices = set()
    lines = map(lambda s: s.split(), read_input(FilePath.DIJKSTRA))

    for line in lines:
        edges = []
        for i in range(1, len(line)):
            u, length = map(int, line[i].strip().split(','))
            edges.append((u, length))
            vertices.add(u)

        vertex = int(line[0])
        g[vertex] = edges
        vertices.add(vertex)

    return g, len(vertices)


def compute_answer(shortest_paths, reported_vertices):
    return ','.join([str(shortest_paths[v]) for v in reported_vertices])


def dijkstra_shortest_path(g, vertices, default_distance=1000000):
    dist = [default_distance] * (vertices + 1)
    dist[1] = 0
    visited = [False] * (vertices + 1)

    def get_min_dist_vertex():
        min_dist = sys.maxsize

        for v in range(1, vertices + 1):
            if dist[v] < min_dist and not visited[v]:
                min_dist = dist[v]
                min_index = v

        return min_index

    def compute(vertices):
        while vertices > 0:
            u = get_min_dist_vertex()
            visited[u] = True
            neighbours = g.get(u)
            for n, l in neighbours:
                dist[n] = min(dist[u] + l, dist[n])
            vertices-=1

        return dist

    return compute(vertices)


data, num_nodes = get_data()
shortest_paths = dijkstra_shortest_path(data, num_nodes)

print('Dijkstra:', compute_answer(shortest_paths, nodes_to_report()))

