	else{
	    // 直線の単位ベクトルを求める
	    var unit = getUnitVector(new Vector2D(line.point1.x - line.point2.x,line.point1.y - line.point2.y));
	    // 射影点から交点までの長さを求める
	    var length = Math.sqrt((circle.r * circle.r) - getNorm(subtractVector(pr,circle.center)));
	    var crossPoints = [];
