#include <iostream>
#include <vector>
#include <algorithm>
const int MAX_W = 10000;
using namespace std;

int s = MAX_W;

int minCostSort(vector<int>& A) {
    int ret = 0;

    vector<bool> V(A.size());
    vector<int> B = A;
    vector<int> T(MAX_W+1);
    for (auto i = 0; i < A.size(); i++) {
        V[i] = false;
    }
    sort(B.begin(), B.end());
    for (auto i = 0; i < A.size(); i++) {
        T[B[i]] = i;
    }

    for (auto i = 0; i < A.size(); i++) {
        if (V[i]) continue;

        int cur = i;
        int S = 0;
        int m = MAX_W;
        int an = 0;
        while (1) {
            V[cur] = true;
            an++;
            int v = A[cur];
            m = min(m, v);
            S += v;
            cur = T[v];
            if (V[cur]) break;
        }
        ret += min(S + (an-2)*m, m + S + (an+1)*s);
    }
    return ret;
}

