    int n;
    cin >> n;

    vector<int> W(n);
    for (int i = 0; i < n; i++) {
        cin >> W[i];
        s = min(s, W[i]);
    }

    int ans = minCostSort(W);
    cout << ans << endl;
    return 0;
}

/**
 * Given an array A of n elements, find three indices i, j and k such that A[i]^2 + A[j]^2 = A[K]^2
 * O(n2) time complexity and O(1) space complexity
 */

#include <iostream>
#include <vector>
#include <algorithm>


std::vector<int> squareSum( std::vector<int> & arr ) {
	std::vector<int> indices{ -1, -1, -1 };
	if ( arr.size() < 3 ) {
		return indices;
	}
	std::sort(arr.begin(), arr.end());

	for ( size_t i = 0; i < arr.size(); ++i ) {
		arr[i] = arr[i] * arr[i];
	}

	for ( size_t k = arr.size()-1; k >= 2; k-- ) {
		size_t i = 0;
		size_t j = k-1;
		while ( i < j ) {
			if ( arr[i] + arr[j] == arr[k] ) {
				indices[0] = i;
				indices[1] = j;
				indices[2] = k;
				return indices;
			}
			if ( arr[i] + arr[j] < arr[k] ) {
				i++;
			} else {
				j--;
			}
		}
	}
	return indices;
}

