function binarySearch(arr, val) {
    let left = 0;
    let right = arr.length - 1;
    let middle;
    let found = false;
    while (left <= right) {
        middle = Math.floor((left + right) / 2);
        if (arr[middle] === val) {
            found = true;
            break;
        } else if (arr[middle] < val) {
            left = middle + 1;
        } else {
            right = middle - 1;
        }
    }
    return found ? middle : -1;
}

