class Point{
public:
	long double x,y;
	Point(){}
	Point(long double xx,long double yy){
		x=xx;
		y=yy;
	}
	Point operator +(Point p){
		return Point(x+p.x,y+p.y);
	}
	Point operator -(Point p){
		return Point(x-p.x,y-p.y);
	}
	Point operator *(long double a){
		return Point(a*x,a*y);
	}
	Point operator /(long double a){
		return Point(x/a,y/a);
	}
	long double abs(){
		return sqrt(norm());
	}

	long double norm(){
		return x*x+y*y;
	}
};

