function big_multiply(A, B)
{
    var m, n, mn, i, j, carry, tmp;
    var buf, a1, a2;
    
    if(A.length > B.length){
        m = A.length;
        n = B.length;
        a1 = A.split(/(?!$)/);
        a2 = B.split(/(?!$)/);
    }
    else{
        m = B.length;
        n = A.length;
        a1 = B.split(/(?!$)/);
        a2 = A.split(/(?!$)/);
    }
    
    mn = m + n;
    if(mn < 7) return 0;
    buf = new Array(mn+1);
    for(j=0;j<=mn;++j) buf[j] = 0;
    
    for(j=m-1;j>=0;--j){
        for(carry = 0,i=n-1;i>=0;--i){
            tmp = parseInt(a1[j]) * parseInt(a2[i]) + buf[i+j+1] + carry;
            buf[i+j+1] = tmp % 10;
            carry = parseInt(tmp / 10);
        }
        buf[j] = carry;
    }
    
    for(j=0;j<=mn;++j){
        if(buf[j] > 0) break;
    }
    
    return (mn - j >= 7) ? 1 : 0;
}

