function calc(num){
    if(arr[arr.length-1] > num){
        for(var i=0;i<arr.length;i++){
            if(arr[i]>num){
                return i;
            }
        }
    }
    start:for(var i = arr[arr.length-1]+(arr[arr.length-1]%2==0?1:2); i<=num; i+=2){
       for(var j=0;j<arr.length;j++){
          if(i%arr[j]==0){
             continue start;
          }
          if(arr[j]>=Math.sqrt(i)){
             break;
          }
       }
       arr.push(i);
    }
    return arr.length;
}

