var maxSubArray = function (nums) {
  if (nums.length == 0) return 0;
  var maxSub = nums[0];
  var currentMax = nums[0];

  for (var i = 1; i < nums.length; i++) {
    currentMax = max(nums[i], currentMax + nums[i]);
    if (currentMax > maxSub) maxSub = currentMax;
  }

  return maxSub;
};

var max = function (i, j) {
  return i > j ? i : j;
};

