inline ll solve(int w,int h,int k){
	ll ans=0;
	FOR(y,1,w){
		++ans;
		For(z,2,h-1){
			if (1ll*y*z+1ll*z*(w-y)-__gcd(z,y)-__gcd(w-y,z)-w<=2*k-2) ++ans;
			int l=1,r=z-1,tmp=__gcd(w-y,z),L=0,lim=2*k-2;
			while (l<=r){
				int mid=l+r>>1;
				if (1ll*y*z+1ll*(w-y)*mid-2-tmp<=lim) L=mid,l=mid+1;
					else r=mid-1;
			}
			int ret=2*L,R=L;
			For(x,L+1,z-1){
				if (1ll*y*z+1ll*(w-y)*x-y-min(z-x,w)-tmp>lim){R=x-1;break;}
				if (1ll*y*z+1ll*(w-y)*x-tmp-__gcd(x,y)-__gcd(w,z-x)<=lim){
					ret+=2;
				}
			}
			ans+=ret;
			if (R==0) break;
		}
	}
	return ans;
}

