int isPrime(int i) {
    for(int j = 2; j * j <= i; j++)
        if(i % j == 0)  return 0;
    return 1;
}

int reserve(int num) {
    int ret = 0;
    while(num) {
        ret = ret * 10 + num % 10;
        num /= 10;
    }
    return ret;
}

int main() {
    int num = readInt();
    if(isPrime(num) && isPrime(reserve(num)))
        printf("yes");
    else
