struct Node
{
	int data;
	struct Node* next;
};
struct Node *front,*rear;

// Linked List implementation on Queues.

void enqueue(int x)
{
	// this operation will be performed in constant time ie. O(1)
	struct Node *temp;

	temp = (struct Node*)malloc(sizeof(struct Node));
	temp->data = x;
	temp->next = NULL;

	if(front==NULL && rear == NULL)
	{
		front =rear =temp;
		return;
	}
	rear->next = temp;
	rear = temp;
	
}

void dequeue()
{
	struct Node *temp = front;

	if(front==NULL)
	{
		printf("Error : QUEUE is empty!!");
		return;
	}
	if(front==rear)
		front = rear = NULL;

	else
		front = front->next;

	free(temp);
}

int pfront()
{	
	int a;
	a = front->data;

	return(a);
}

int main()
{
	front = NULL;
	rear = NULL;

	enqueue(2);
	printf("front - %d ",pfront());
	enqueue(3);
	printf("front - %d ",pfront());
	enqueue(5);
	printf("front - %d ",pfront());
	dequeue();
	dequeue();
	printf("front - %d ",pfront());
}

