void sift(int array[], int l, int r) {
    int i, j, x, k;
    i = l;
    j = 2 * l + 1;

    x = array[l]; //parent
    if ((j < r) && (array[j] < array[j + 1]))
        j++;
    while ((j <= r) && (x < array[j])) {
        k = array[i];
        array[i] = array[j];
        array[j] = k;
        i = j;
        j = 2 * j + 1;
        if ((j < r) && (array[j] < array[j + 1]))
            j++;
    }
}

int heap_sort(int arr[], int n) {
    if (n == 0) {
        return 0;
    }
    int l, r, x, i;
    l = n / 2;
    r = n - 1;
    while (l > 0) {
        l--;
        sift(arr, l, r);
    }
    while (r > 0) {
        x = arr[0];
        arr[0] = arr[r];
        arr[r] = x;
        r--;
        sift(arr, l, r);
    }
    return 1;
}

