using namespace std;

long long modmul(long long a, long long b, long long mod){
	return a*b%mod;
}

long long modnjo(long long a, long long n, long long mod){
	if(n==0)return 1;
	if(n%2==1)return a*modnjo(a, n-1, mod)%mod;
	return modnjo(a*a%mod, n/2, mod);
}

long long modinv(long long a, long long mod){
	return modnjo(a, mod-2, mod);
}

long long moddiv(long long a, long long b, long long mod){
	return modmul(a, modinv(b, mod), mod);
}

