vector<vector<pair<int, long long> > > edges;

void dfs(int p){
	for(int i=0;i<edges[p].size();i++){
		if(!isVisit[edges[p][i].first]){
			isVisit[edges[p][i].first] = 1;
			for(int j=0;j<SosuNum;j++){
				if(edges[p][i].second > 0)cst[edges[p][i].first][j] = modmul(cst[p][j], edges[p][i].second, Sosu[j]);
				else cst[edges[p][i].first][j] = moddiv(cst[p][j], -edges[p][i].second, Sosu[j]);
			}
			dfs(edges[p][i].first);
		}
	}
}


