using namespace std;
struct node
{
    bool word_end;
    map<char,node*> m;
};
node* getnode(){
    node* temp = new node;
    temp->word_end =false;
    temp->m = map<char,node*>();
    return temp;
}
node* insert(node* start,string s){
    int i=0,n=s.size();
    for(i=0;i<n;i++)
    {
        map<char,node*>::iterator it = start->m.find(s[i]);
        if(it==start->m.end())
        {
            node* temp = getnode();
            start->m.insert(make_pair(s[i],temp));
            start = temp;
        }
        else
            start = (*it).second;
    }
    start->word_end = true;
}
bool find(node* start,string s){
    int i=0,n=s.size();
    for(i=0;i<n;i++)
    {
        map<char,node*>::iterator it = start->m.find(s[i]);
        if(it==start->m.end())
            return false;
        start = (*it).second;
    }
    if(start->word_end==true)
        return true;
    else 
        return false;
}
bool delete_util(node* start,string s,int begin,int end){
    if(begin==end)
    {
        if(!start->word_end)
            return false;
        else
        {
            if(!start->m.size())
            {
                free(start);
                return true;
            }
            else
                start->word_end = false;
        }
    }
    else
    {
        map<char,node*>::iterator it = start->m.find(s[begin]);
        if(it==start->m.end())
            return false;
        bool temp = delete_util((*it).second,s,begin+1,end);
        if(temp==false)
            return false;
        else
        {
            start->m.erase(s[begin]);
            if(start->m.size()==0)
            {
                free(start);
                return true;
            }
            else
                return false;
        }
    }
}
void delete_node(node* start,string s){
    delete_util(start,s,0,s.size());
}
