void bubblesort(int A[],int n)
{
	int i,k,temp;
	for(k=0;k<n-1;k++)
	{
		int flag=0;
		for(i=0;i<n-k-1;i++)
		{
			if(A[i]>A[i+1])
			{
				temp=A[i+1];
				A[i+1]=A[i];
				A[i]=temp;
				flag=1;
			}
		}
		if(flag==0)
		break;
	}
}
