typedef long long ll;
const int MaxN = 1e5 + 5;
ll cnt1[MaxN + 5],cnt2[MaxN + 5],a[MaxN + 5],b[MaxN + 5],c[MaxN + 5],n;

ll cmp1(ll x, ll y){
	return x < y;
}
ll cmp(ll x, ll y){
	return x > y;
}

