using namespace std;

const int dy[] = {-1, 0, 1, 0};
const int dx[] = {0, -1, 0, 1};

struct State {
  char field[4][4];
  int cost;
  explicit State(int c): cost(c) {}
};

struct Drop {
  int y, x, dir;
  Drop(int y, int x, int dir): y(y), x(x), dir(dir) {}
};

void blowup(char field[4][4], int sy, int sx) {
  vector<Drop> drops;
  field[sy][sx] = 0;
  for (int dir = 0; dir < 4; ++dir) {
    drops.push_back(Drop(sy, sx, dir));
  }
  while (!drops.empty()) {
    for (int i = 0; i < int(drops.size()); ) {
      Drop& d = drops[i];
      d.y += dy[d.dir];
      d.x += dx[d.dir];
      if (d.y < 0 || d.y >= 4 || d.x < 0 || d.x >= 4) {
        drops.erase(drops.begin()+i);
        continue;
      }
      if (field[d.y][d.x] != 0) {
        field[d.y][d.x] += 1;
        drops.erase(drops.begin()+i);
        continue;
      }
      ++i;
    }
    for (int y = 0; y < 4; ++y) {
      for (int x = 0; x < 4; ++x) {
        if (field[y][x] > 4) {
          field[y][x] = 0;
          for (int dir = 0; dir < 4; ++dir) {
            drops.push_back(Drop(y, x, dir));
          }
        }
      }
    }
  }
}

int main() {
