  State init_state(0);

  for (int y = 0; y < 4; ++y) {
    for (int x = 0; x < 4; ++x) {
      int d; scanf("%d", &d);
      init_state.field[y][x] = d;
    }
  }

  queue<State> Q;
  Q.push(init_state);
  int ans = -1;
  while (!Q.empty()) {
    State s = Q.front(); Q.pop();

    if (memcmp(s.field, goal, sizeof(goal)) == 0) {
      ans = s.cost;
      break;
    }

    if (s.cost < 5) {
      for (int y = 0; y < 4; ++y) {
        for (int x = 0; x < 4; ++x) {
          if (s.field[y][x] == 0) {
            // do nothing
          } else {
            State next(s.cost+1);
            memcpy(next.field, s.field, sizeof(s.field));
            next.field[y][x] += 1;
            if (next.field[y][x] == 5) { blowup(next.field, y, x); }
            Q.push(next);
          }
        }
      }
    }
  }

  printf("%d\n", ans);
}

// Binary Gap

int binaryGap(int n) {
    int maxDist = 0;
    int curr = -1;
    int prev = -1;
    for (int i = 0; i < 32; i++) {
        if (n>>i&1) {
            prev = curr;
            curr = i; 
            if (prev != -1) maxDist = curr - prev > maxDist?curr - prev: maxDist;
        }
    }
    return maxDist;
}

