int getArea(vector<pii> &v){
    int px[4] = {INF,0,INF,0};
    int py[4] = {INF,INF,0,0};
    for(int i = 0 ; i < (int)v.size() ; i++){
	int x = v[i].first,y = v[i].second;
	if(y < py[0]){
	    px[0] = px[1] = x;
	    py[0] = py[1] = y;
	}else if(y == py[0]){
	    if(x < px[0]){
		px[0] = x;
	    }else if(px[1] < x){
		px[1] = x;
	    }
	}
	if(py[2] < y){
	    px[2] = px[3] = x;
	    py[2] = py[3] = y;
	}else if(py[2] == y){
	    if(x < px[2]){
		px[2] = x;
	    }else if(px[3] < x){
		px[3] = x;
	    }
	} 
    }
    return ((px[1]-px[0]+1)+(px[3]-px[2]+1))*(py[2]-py[0]+1)/2;
}
 
