#include <stdio.h>
#include <stdlib.h>

/* A structure of linked list ListNode */
struct ListNode {
  int data;
  struct ListNode *next;
} *head;

void initialize(){
    head = NULL;
}

/*
Given a Inserts a ListNode in pTemp of a singly linked list.
*/
void insert(struct ListNode **head, int data) {
    /* Create a new Linked List ListNode */
    struct ListNode* newNode = (struct ListNode*) malloc(sizeof(struct ListNode));
    newNode->data  = data;
    /* Next pointer of new ListNode will point to head ListNode of linked list  */
    newNode->next = *head;
    /* make new ListNode as new head of linked list */
    *head = newNode;
}

int getLength(struct ListNode *head){
    /* Input Validation */
    if (head == NULL) {
       printf("Error : Invalid ListNode pointer !!!\n");
       return 0;
    }

    int length =0;
    while(head != NULL){
        head = head->next;
        length++;
    }
    return length;
}

// Prints a linked list from head ListNode till tail ListNode
void printLinkedList(struct ListNode *head) {
  while (head != NULL) {
     printf("%d", head->data);
     head = head->next;
     if(head != NULL)
         printf("-->");
  }
}

/* Reverses a given linked list, and return the head pointer of reversed linked list */
struct ListNode* reverseLinkedList(struct ListNode *head) {
    struct ListNode *previous, *current, *next;
    previous = NULL;
    current = head;

    while (current != NULL) {
        next  = current->next;
        current->next = previous;
        previous = current;
        current = next;
    }
    return previous;
}

// Remove duplicates from a sorted list
void removeDuplicates(struct ListNode **head) {
    struct ListNode* current = *head;
    if (current == NULL) return; // do nothing if the list is empty
    // Compare current ListNode with next ListNode
    while(current->next!=NULL) {
        if (current->data == current->next->data) {
            struct ListNode* nextNext = current->next->next;
            free(current->next);
            current->next = nextNext;
        }
        else {
            current = current->next; // only advance if no deletion
        }
    }
}

int main() {
  struct ListNode *commonNodes;
  initialize();
  /* Creating a linked List*/
  insert(&head, 3);
  insert(&head, 8);
  insert(&head, 13);
  insert(&head, 13);
  insert(&head, 35);
  insert(&head, 120);
  insert(&head, 200);
  insert(&head, 200);
  insert(&head, 516);
  insert(&head, 516);
  printf("\nLinked List\n");
  head = reverseLinkedList(head);
  printLinkedList(head);
  removeDuplicates(&head);
  printf("\nLinked List\n");
  printLinkedList(head);
}

package adventofcode;

import java.util.*;

/**
 * http://adventofcode.com/2017/day/12
 */
@SuppressWarnings("Duplicates") public class DigitalPlumber_12 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        StringBuilder builder = new StringBuilder();
        while (scanner.hasNextLine()) {
            String s = scanner.nextLine();
            if (s.equals("1"))
                break;
            if (s.length() > 0)
                builder.append(s).append("\n");
        }
        System.out.println(solve2(builder.toString()));
    }

    private static int solve(String s) {
        if (s == null || s.length() == 0)
            return 0;
        Map<Integer, Set<Integer>> map = new HashMap<>();
        String[] a = s.split("\n");
        for (int i = 0; i < a.length; i++) {
            String[] aa = a[i].split(" ");
            int key = Integer.parseInt(aa[0]);
            if (!map.containsKey(key))
                map.put(key, new HashSet<>());
            for (int j = 2; j < aa.length; j++) {
                String value = aa[j].endsWith(",") ? aa[j].substring(0, aa[j].length() - 1) : aa[j];
                map.get(key).add(Integer.parseInt(value));
            }
        }

        return bfs(map, 0).size();

    }

    private static int solve2(String s) {
        if (s == null || s.length() == 0)
            return 0;
        Map<Integer, Set<Integer>> map = new HashMap<>();
        String[] a = s.split("\n");
        for (int i = 0; i < a.length; i++) {
            String[] aa = a[i].split(" ");
            int key = Integer.parseInt(aa[0]);
            if (!map.containsKey(key))
                map.put(key, new HashSet<>());
            for (int j = 2; j < aa.length; j++) {
                String value = aa[j].endsWith(",") ? aa[j].substring(0, aa[j].length() - 1) : aa[j];
                map.get(key).add(Integer.parseInt(value));
            }
        }
        int count = 0;
        while (!map.isEmpty()) {
            int next = map.keySet().iterator().next();
            Set<Integer> group = bfs(map, next);
            for (Integer key : group) {
                map.remove(key);
            }
            count++;
        }
        return count;

    }

    private static Set<Integer> bfs(Map<Integer, Set<Integer>> map, int source) {
        Set<Integer> group = new HashSet<>();
        Set<Integer> visited = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.add(source);
        visited.add(0);
        while (!queue.isEmpty()) {
            Integer current = queue.remove();
            group.add(current);
            for (Integer nei : map.get(current)) {
                if (!visited.contains(nei)) {
                    visited.add(nei);
                    queue.add(nei);
                }
            }
        }
        return group;
    }
}

