    if(a[i] > 0) gou += a[i];
    if(q.size() < k) continue;
    mn = max(ans - gou, mn);
    if(q.front() > 0) gou -= q.front();
    q.pop();
  }
  gou = 0;
  rep(i, 0, n) {
    qq.push(a[i]);
    if(a[i] < 0) gou -= a[i];
    if(qq.size() < k) continue;
    mx = max(mx, ans - gou);
    if(qq.front() < 0) gou += qq.front();
    qq.pop();
  }

  cout << max(mn, mx) << endl;
}

