const double PI = atan(1.0) * 4.0;

const double EPS = 1.0e-10;
const int MAX_N = 410;
int n;
int x[MAX_N], y[MAX_N];
bool used[MAX_N];

double atan3(int x1, int y1, int x2, int y2) {
	double dot = x1 * x2 + y1 * y2;
	double det = x1 * y2 - x2 * y1;
	double a = atan2(det, dot);
	return a;
}

double distance(int x1, int y1, int x2, int y2) {
	double dx = x2 - x1;
	double dy = y2 - y1;
	return sqrt(dx * dx + dy * dy);
}

void solve() {
	memset(used, 0, sizeof(used));

	vector<P> v;
	int px = 0, py = 0;
	int prevx = 0, prevy = -1;
	double dist = 0.0;
	int visit = 0;
	while(visit < n) {
		v.clear();
		rep(i,n) {
			if(!used[i]) {
				double angle = atan3(x[i]-px, y[i]-py, px-prevx, py-prevy);
				double dd = distance(px, py, x[i], y[i]);
				P p = { angle, dd, i };
				v.push_back(p);
			}
		}
		sort(v.begin(), v.end());

		int idx = v[0].idx;
		dist += v[0].dist;
		prevx = px;
		prevy = py;
		px = x[idx];
		py = y[idx];
		used[idx] = true;
		visit++;
	}
	printf("%.1f\n", dist);
}

