bool visited[101][100001] = {false};
long long int memo[101][100001] = {0};
int weight[101] = {0};
int value[101] = {0};

long long int knap(int N, int W)
{
    
    if (!visited[N][W])
    {
        visited[N][W] = true;
        if (N == 0 || W == 0)
        {
            memo[N][W] = 0;
        } 
        else if (weight[N] > W)
        {
            memo[N][W] = knap(N-1, W);
        }
        else
        {
            memo[N][W] = max(knap(N-1, W), value[N] + knap(N-1, W - weight[N]));
        }
        return memo[N][W];
    }
    else
    {
        return memo[N][W];
    }
    
}

int main()
{
    int N, W, i, j;
    cin>>N>>W;

    for(i=1; i<=N; i++)
    {
        cin>>weight[i]>>value[i];
    }

    cout<<knap(N, W)<<endl;
    return 0;
}

#include<stdio.h>
