inline int _log2(int x)
{
	int res = 0;
	while (x > 1)
	{
		x >>= 1;
		res++;
	}
	return res;
}

void init_pow2()
{
	pow2[0] = 1;
	for (int i = 1; i <= 20; i++)
	{
		pow2[i] = pow2[i - 1] * 2;
	}
}

void build_st()
{
	init_pow2();
	for (int i = 1; i <= 20; i++)
	{
		for (int j = 0; j < n; j++)
		{
			st[j][i] = max(st[j][i - 1], st[j + pow2[i - 1]][i - 1]);
		}
	}
}

int get_max(int l, int r)
{
	int x = _log2(r - l + 1);
	return max(st[l][x], st[r - pow2[x] + 1][x]);
}

