 * Given a binary tree, print all the paths whose sum is equal to k
 *          1
 *       /     \
 *     3        -1
 *   /   \     /   \
 *  2     1   4     5                        
 *       /   / \     \                    
 *      1   1   2     6
 *
 * For k = 5:
 * 3 2 
 * 3 1 1 
 * 1 3 1 
 * 4 1 
 * 1 -1 4 1 
 * -1 4 2 
 * 5 
 * 1 -1 5     
 */

#include <iostream>
