/**
 * Binary search algorithm.
 *
 * @param int a Search array
 * @param int find Data to search
 * @param int n Number of data in search array
 *
 * @return int Index of found data or -1
 */
int binary_search(int *a, int find, int n)
{
    int start = 0;
    int end = n - 1;
    int mid = n / 2;

    while (start <= end) {
        if (a[mid] == find) {
            return mid;
        }

        if (find < a[mid]) {
            end = mid - 1;
        } else {
            start = mid + 1;
        }

        mid = (start + end) / 2;
    }

    return -1;
}

