def inverse_captcha_v1(data):
    """Inverse Captcha."""
    total = 0
    ll = len(data)
    for i in range(0, ll):
        if data[i] == data[(i + 1) % ll]:
            total += int(data[i])

    return total


def inverse_captcha_v2(data):
    """Inverse Captcha."""
    total = 0
    ll = len(data)
    for i in range(0, ll / 2):
        if data[i] == data[i + ll / 2]:
            total += int(data[i])

    return 2 * total


