using namespace std;
constexpr int MAX = 600000;
bitset<MAX> Mask;
int LSB = 0;
int MSB = MAX - 1;
bool place(const int d)
{
    if (d > MAX) {
        return not Mask.all();
    } else {
        const int bit = MAX - d;
        if (MSB < bit) {
            return false;
        } else {
            int pos = bit;
            while (Mask[pos]) {
                Mask[pos] = 0;
                pos++;
            }
            Mask[pos] = 1;
            if (pos == MSB) {
                while (pos >= 0 and Mask[pos]) {
                    pos--;
                }
                MSB = pos;
            }
            return true;
        }
    }
}

