		}
		else {
			if (((lbA - ans_a) + (lbA / A * T - ans_t)) <
				(lbT - ans_t) + (lbT / T * A - ans_a)) {
				ans_a = lbA;
				ans_t = lbA / A * T;
			}
			else {
				ans_t = lbT;
				ans_a = lbT / T * A;
			}
		}
