def side(A, B, P):
	dx = B.x - A.x
	dy = B.y - A.y

	a = dy
	b = -dx
	c = -(a * B.x + b * B.y)

	return a * P.x + b * P.y + c


def quickhull(points):
	A = B = points[0]
	for p in points[1:]:
		x = p.x
		y = p.y
		if A.x < x:
			A = p
		if B.x > x:
			B = p

	s1 = set()
	s2 = set()
	for p in points:
		if p is not A and p is not B:
			if side(A, B, p) > 0:
				s1.add(p)
			else:
				s2.add(p)


	def QH(A, B, P):
		if len(P) == 0:
			return []
		elif len(P) == 1:
			C = P.pop()
			draw.polygon([A.x, A.y, B.x, B.y, C.x, C.y])
			return [C]

		dx = B.x - A.x
		dy = B.y - A.y
		a = dy
		b = -dx
		c = -(a * B.x + b * B.y)

		C = None
		D = None
		for p in P:
			d = a * p.x + b * p.y + c
			if C is None or d > D:
				C = p
				D = d

		draw.polygon([A.x, A.y, B.x, B.y, C.x, C.y])
		assert C is not None

		s1 = set()
		s2 = set()
		for p in P:
			if p is C:
				continue

			if side(A, C, p) > 0:
				s1.add(p)
			elif side(C, B, p) > 0:
				s2.add(p)

		#print s1, s2
		return QH(A, C, s1) + [C] + QH(C, B, s2)


	return [A] + QH(A, B, s1) + [B] + QH(B, A, s2)


