    return this.data
  }
}

class BST {
  constructor() {
    this.root = null
  }

  // inserts iteratively
  insert(data) {
    let newNode = new BNode(data, null, null)

    if (!this.root) {
      this.root = newNode
    } else {

      let current = this.root
      let parent;

      while (true) {
        parent = current

        if (data < current.data) {
          current = current.left

          if (!current) {
            parent.left = newNode
            break;
          }
        } else {
          current = current.right

          if (!current) {
            parent.right = newNode
            break;
          }
        }
      }
    }
  }
}

