    double R=1.0/sqrt(3.0);
    P a=P(R,0);
    P b=P(R-0.5*sqrt(3.0),0.5);
    
    double lc=lcm(n,3);
    double ti=2.0*PI/lc;

    P c=a,d=b;

    if(lc==3){
      printf("0.433013\n");
      continue;
    }
    
    double T=1e9;
    for(int i=0;i<n;i++){
