int Memoized_Cut_Rod(int p[], int n) {
    double r[n + 1]; // Maximum Revenue Earnable
    int i;
    for (i = 0; i <= n; i++) {
        r[i] = -INFINITY;
    }
    return Memoized_Cut_Rod_Aux(p, n, r);
}

int Memoized_Cut_Rod_Aux(int p[], int n, double r[]) {
    double q = 0;
    int i;
    if (r[n] >= 0) {
        return (int)r[n];
    }
    if (n == 0) {
        q = 0;
    } else if (n != 0) {
        q = -INFINITY;
        for (i = 0; i < n; i++) {
            q = max(q, p[i] + Memoized_Cut_Rod_Aux(p, n - i - 1, r));
        }
        r[n] = q;
    }
    return (int)q;
}

