	dp[n][0] = 1;
	for(int i = n - 1; i >= 0; i--)
		dp[i] = dp[i + 1] | (dp[i + 1] << s[i].size());

	cli.push_back(0);
	for(int i = 0; i < n; i++)
	{
		for(char c: s[i])
			cli.push_back(c);

		last[i + 1] = cli.size() - 1;
	}

	for(int i = 1; i < (int)cli.size(); i++)
		bs[cli[i] - 'a'][i] = 1;

	for(int i = 0; i < 26; i++)
		pref_bs[i] = (i == 0) ? (bs[0]) : (pref_bs[i - 1] | bs[i]);

	string answer = "";
	curr[0] = 1;
	for(int c_l = 0; c_l < k; c_l++)
	{
		char let, low = 'a', high = 'z', mid;
		while(low <= high)
		{
			mid = (low + high) >> 1;

			if(check(mid, c_l))
				let = mid, high = mid - 1;
			else 
				low = mid + 1;
		}

		temp = (curr << 1) & bs[let - 'a'];

		bool ok = 0;
		for(int i = 0; i < n; i++)
		{
			if(curr[last[i]]) ok = 1;
			if(ok && cli[last[i] + 1] == let)
			{
				temp[last[i] + 1] = 0;
				if(c_l + (int)s[i].size() <= k && dp[i + 1][k - c_l - (int)s[i].size()]) 
					temp[last[i] + 1] = 1;
			}
		}

		answer += let;
		curr = temp;
	}

	cout << answer << endl;
}

