	cin >> h >> w >> n;
	fo(i, 1, n) cin >> bcell[i].fi >> bcell[i].se;
	
	precompute(h+w);
	sort(bcell+1, bcell+n+1);
	bcell[++n] = {h, w};
	
	cout << solve(n);  
}

