#include <stdio.h>
#include <stdlib.h>

typedef struct node {
    int coef, exp;
    struct node *next;
} Node;

Node* get_node()
{
    return (Node*) malloc(sizeof(Node));
}

Node* attach_node(int coef, int exp, Node* poly){
    Node *new_node;

    new_node = get_node();
    new_node->coef = coef;
    new_node->exp = exp;
    new_node->next = NULL;

    if( poly == NULL )
    {
        poly = new_node;
        new_node->next = poly;
    }
    else
    {
        new_node->next = poly->next;
        poly->next = new_node;
        poly = new_node;
    }

    return poly;
}

Node* read_poly(int n){
    Node *exp = NULL;
    int i, c, e;

    for(i = 0; i < n; i++)
    {
        scanf("%d%d", &c, &e);
        exp = attach_node(c, e, exp);
    }

    return exp;
}

Node* add_poly(Node *poly1, Node *poly2)
{
    Node *exp3 = NULL, *tpoly1, *tpoly2;

    tpoly1 = poly1->next;
    tpoly2 = poly2->next;

    do
    {
         if( tpoly1->exp == tpoly2->exp )
         {
             exp3 = attach_node(tpoly1->coef + tpoly2->coef, tpoly1->exp, exp3);
             tpoly1 = tpoly1->next;
             tpoly2 = tpoly2->next;
         }
         else if(tpoly1->exp > tpoly2->exp)
         {
             exp3 = attach_node(tpoly1->coef, tpoly1->exp, exp3);
             tpoly1 = tpoly1->next;
         }
         else
         {
             exp3 = attach_node(tpoly2->coef, tpoly2->exp, exp3);
             tpoly2 = tpoly2->next;
         }
    } while ( tpoly1 != poly1->next || tpoly2 != poly2->next );

    return exp3;
}

void display(Node *e) {
    Node *temp = e->next;
    do {
        printf("%dx^%d  ", temp->coef, temp->exp);
        temp = temp->next;
    } while (temp != e->next);
    printf("\n");
}

