    }
    
    sort(av.begin(), av.end());

    UnionFind uf(Q+1);
    aiv[av[0].second].push_back(0);
    fornum(i,1,av.size()){
        if(av[i].first != av[i - 1].first){
            As.push_back(moddiv(powl(10, av[i].first - av[i - 1].first) - 1 + MOD, 9));
        }else{
            uf.unite(av[i].second, av[i - 1].second);
        }
        aiv[av[i].second].push_back(As.size());
    }

    nv.assign(1 << Q, 1);
    fornum(i, 0, 1 << Q)
    {
        ll a = 0;
        fornum(j,0,Q){
            if(i&(1<<j)){
                fornum(k,0,2){
                    ll ii = aiv[j][k];
                    if(a&(1ll<<ii))
                        continue;
                    if(ii>0&&(a&(1ll<<(ii-1)))){
                        nv[i] = moddiv(nv[i] * (As[ii - 1] + 1), As[ii - 1]);
                    }
                    if(ii<As.size()&&(a&(1ll<<(ii+1)))){
                        nv[i] = moddiv(nv[i] * (As[ii] + 1), As[ii]);
                    }
                    a |= (1ll << ii);
                }
            }
        }
    }

    dp.assign(10, vector<ll>(1 << Q, 0));
    dp[0][0] = powl(10, av[0].first) * powl(10, N - av[av.size() - 1].first) % MOD;
    fornum(i,0,As.size()){
