                if(i==0){
                    if(l[k]==av[0].first&&!a){
                        break;
                    }
                }
            }
            if(k<Q){
                continue;
            }
            
            dp[i + 1][j] += dp[i][j];
            for (k = j; k > 0;k=(k-1)&j){
                dp[i + 1][j] += dp[i][j ^ k] * nv[k];
                dp[i + 1][j] %= MOD;
