                LCS_Table[i][j].direction = 's';
            } else if (LCS_Table[i-1][j].max_occurance >= LCS_Table[i][j-1].max_occurance){
                LCS_Table[i][j].max_occurance = LCS_Table[i-1][j].max_occurance;
