def search_min(nums: list[int]):
    lo = 0
    hi = len(nums) - 1
    while lo < hi:
        while lo < len(nums) and nums[lo] == nums[lo + 1]:
            lo = lo + 1
        while hi >= 0 and nums[hi] == nums[hi - 1]:
            hi = hi - 1
        mid = (lo + hi) // 2
        if mid < hi and nums[mid + 1] < nums[mid]:
            return nums[mid + 1]
        if mid > lo and nums[mid] < nums[mid - 1]:
