int n;

int solve(string& s, int i, bool zero)
{
    if(s == string(s.size(), 'B')){
        return s.size();
    }else if(s == string(s.size(), 'R')){
        return 0;
    }

    string t;
    int j;

    t = s;
    j = (i + n - 1) % t.size();
    t.erase(j, 1);
    int ret = solve(t, j, zero);

    if(zero){
        t = s;
        j = (i + n) % t.size();
        t.erase(j, 1);
        ret = max(ret, solve(t, j, false));
    }

    return ret;
}

