function main(){
  var read = 0;
  var resultCase = 1;
  while(true){
    var maxWeight = +input[read++];
    if(!maxWeight){
      break;
    }
    
    var treasures = +input[read++];

    // dp[宝][重さ] = 価値
    var dp = new Array(treasures + 1);
    dp[0] = new Int32Array(maxWeight + 1);

    var resultWeight = 1001;
    var resultCost = 0;
    for(var i = 1; i <= treasures; i++){
      var dpp = dp[i - 1];
      var dpi = dp[i] = new Int32Array(maxWeight + 1);
      
      var c = input[read++].split(",");
      var tv = +c[0];
      var tw = +c[1];

      // 今のお宝のみ持っていく
      dpi[tw] = max(tv, dpp[tw]);

      var dppw;
      for(var w = 1, wlen = maxWeight - tw; w < wlen; w++){
        if(!(dppw = dpp[w]))
          continue;

        var wtw = w + tw;
        var dpiwtw = dpi[wtw] = max(dppw + tv, dpp[wtw]);

        if(dpiwtw > resultCost){
          resultCost = dpiwtw;
          resultWeight = wtw;
        }
        
      }
      
    }

    console.log("Case " + resultCase++ + ":\n" + resultCost + "\n" + resultWeight);

  }
}

