void PUSH( int STACK[] , int ITEM )
{
	if( TOP == MAX - 1 )
	{
		printf("\n STACK OVERFLOW \n");
	}
	else
	{
		TOP = TOP + 1;
		STACK[TOP] = ITEM;
		printf("\n [ %d ] PUSHED into STACK \n",ITEM);
	}
}
int POP( int STACK[] )
{
	int ITEM = -1;
	if( TOP == -1 )
	{
		printf("\n STACK UNDERFLOW \n");
	}
	else
	{
		ITEM = STACK[TOP];
		TOP = TOP - 1;
	}
	return ITEM;
}
