int maxArea(std::vector<int>& height) {
	size_t l = 0;
	size_t r = height.size() - 1;
	int maxAr = std::numeric_limits<int>::min();
	while( l < r ) {
		int curAr = ( std::min(height[l], height[r]) * ( r - l ));
		if ( curAr > maxAr ) {
			maxAr = curAr;
		}
		if ( height[l] < height[r]) {
			l++;
		} else {
			r--;
		}
	}
	return maxAr;
}

