def binarySearch(arr, l, r):
    if l > r:
        return -1

    if l == r:
        return arr[l]

    mid  = (l + r) // 2
    if (mid % 2) == 0:
        if arr[mid] == arr[mid+1]:
            return binarySearch(arr, mid+2, r)
        else:
            return binarySearch(arr, l, mid)
    if (mid % 2) == 1:
        if arr[mid] == arr[mid-1]:
            return binarySearch(arr, mid+1, r)
        else:
            return binarySearch(arr, l, mid-1)

