struct Node
{
	struct Node* prev;
	int data;
	struct Node* next;
		
};
struct Node* head;

void insertatend(int x)
{
	struct Node *temp,*p;
	temp = (struct Node*)malloc(sizeof(struct Node));
	p = (struct Node*)malloc(sizeof(struct Node));

	temp->data = x;
	p=head;

	temp->next = NULL;

	while(p->next!=NULL)
		p = p->next;

	p->next = temp;
	temp->prev = p;
}

void insertatbeg(int x)
{
	struct Node* temp;
	temp  = malloc(sizeof(struct Node));

	temp->data = x;
	temp->prev = NULL;
	temp->next = NULL;

	if(head==NULL)
	{
		head = temp;
		return;
	}
	head->prev = temp;
	temp->next = head;
	head = temp;

