{
	int i, index,flag=0;
	for(i=0; i<TABLE_SIZE; i++)
	{
		index = (i+ele)%TABLE_SIZE;
		if(htable[index] == -1)
		{
			htable[index] = ele;
			flag = 1;
			break;
		}
	}
	if(flag == 0)
		printf("Element cannot be inserted\n");
	else
		printf("Element Successfully Inserted\n");
}

