#include <stdio.h>
#include <stdlib.h>

/*Function Prototypes*/
void ReadElements(int [],int);
void DisplayArray(int [],int);
void CountingSort(int [],int);

int main(){
    int *ArrayPointer;
    int Size;

    printf("Type Array Size :");
    scanf("%d",&Size);

    ArrayPointer = (int *)malloc(sizeof(int)*Size);

    ReadElements(ArrayPointer,Size);

    printf("\nUnsorted Array :");
    DisplayArray(ArrayPointer,Size);

    CountingSort(ArrayPointer,Size);

    printf("\nSorted Array :");
    DisplayArray(ArrayPointer,Size);

    return 0;
}

void ReadElements(int A[],int S){
    int i,E;
    while (i != S){
        printf("%dth Element :",i);
        scanf("%d",&E);
        A[i] = E;
        i = i + 1;
    }
}

void DisplayArray(int A[],int S){
    int i;
    printf("{");
    while (i != S){
        if(i == S-1){
            printf("%d",A[i]);
        }
        else{
            printf("%d, ",A[i]);
        }
        i = i + 1;
    }
    printf("}");
}

void CountingSort(int A[],int S){
    int MaxElement,i,j,Sum;
    MaxElement = A[0];
    i = 1;
    while (i != S){
        if (MaxElement < A[i]){
            MaxElement = A[i];
        }
        i = i + 1;
    }

    int CountArray[MaxElement + 1];
    i = 0;
    while (i != MaxElement + 1){
        CountArray[i] = 0;
        i = i + 1;
    }

    i = 0;
    while (i != S){
        CountArray[A[i]] += 1;
        i = i + 1;
    }

    Sum = CountArray[0];
    i = 1;
    while (i != MaxElement + 1){
        Sum += CountArray[i];
        CountArray[i] = Sum;
        i = i + 1; 
    }

    int B[S];
    i = 0;
    while (i != S){
        CountArray[A[i]] -= 1;
        B[CountArray[A[i]]] = A[i];
        i = i + 1;
    }

    i = 0;
    while (i != S){
        A[i] = B[i];
        i = i + 1;
    }
}

#include <cstdio>
#include <cstring>

#define STRING_LENGTH 300000

using namespace std;

struct sortinfo
{
	int x, y, ord;
};

int l;
char s[STRING_LENGTH], t[STRING_LENGTH / 2];
int rank[STRING_LENGTH * 2], sa[STRING_LENGTH], height[STRING_LENGTH];

void radix_sort(sortinfo *d)
{
	static sortinfo _d[STRING_LENGTH], res[STRING_LENGTH];
	static int c[STRING_LENGTH];
	memset(c, 0, sizeof(c));
	for (int i = 0; i < l; i++)
	{
		c[d[i].y]++;
	}
	for (int i = 1; i <= l; i++)
	{
		c[i] += c[i - 1];
	}
	for (int i = l - 1; i >= 0; i--)
	{
		_d[--c[d[i].y]] = d[i];
	}
	memset(c, 0, sizeof(c));
	for (int i = 0; i < l; i++)
	{
		c[_d[i].x]++;
	}
	for (int i = 1; i <= l; i++)
	{
		c[i] += c[i - 1];
	}
	for (int i = l - 1; i >= 0; i--)
	{
		res[--c[_d[i].x]] = _d[i];
	}
	for (int i = 0; i < l; i++)
	{
		d[i] = res[i];
	}
}

void init_rank()
{
	static int c[256];
	static sortinfo d[STRING_LENGTH];
	int x = 1;
	for (int i = 0; i < l; i++)
	{
		c[(int)s[i]] = 1;
	}
	for (int i = 0; i < 256; i++)
	{
		if (c[i] == 1)
		{
			c[i] = x++;
		}
	}
	for (int i = 0; i < l; i++)
	{
		rank[i] = c[(int)s[i]];
	}
	for (int k = 1; k < l; k <<= 1)
	{
		for (int i = 0; i < l; i++)
		{
			d[i].x = rank[i];
			d[i].y = rank[i + k];
			d[i].ord = i;
		}
		radix_sort(d);
		x = 1;
		rank[d[0].ord] = 1;
		for (int i = 1; i < l; i++)
		{
			rank[d[i].ord] = (d[i].x == d[i - 1].x && d[i].y == d[i - 1].y ? x : ++x);
		}
		if (x == l)
		{
			break;
		}
	}
}

void rank_to_sa()
{
	for (int i = 0; i < l; i++)
	{
		sa[rank[i]] = i;
	}
}

void init_height()
{
	int k = 0;
	for (int i = 0; i < l; i++)
	{
		if (k > 0)
		{
			k--;
		}
		if (rank[i] == l)
		{
			continue;
		}
		for (; s[i + k] == s[sa[rank[i] + 1] + k]; k++) ;
		height[rank[i]] = k;
	}
}

