void pre_order( binary_node_struct * );
// 中序遍历
void in_order( binary_node_struct * );
// 后序遍历
void post_order( binary_node_struct * );
// 树的深度
int get_depth( binary_node_struct * );
// 叶子节点个数
int get_leaf_number( binary_node_struct * );

