int main()
{
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    vector<int> xs(n);
    for (auto &x: xs)
        cin >> x;

    vector<vector<int>> bkt(m);
    for (auto &x: xs) {
        bkt[x % m].push_back(x);
    }
    for (auto &b: bkt) {
        sort(b.begin(), b.end());
    }

    int ans = 0;
    for (int i = 0; i < m; i++) {
        int j = (m - i) % m;

        if (i > j)
            continue;

        if (i == j) {
            ans += bkt[i].size() / 2;
            continue;
        }

        int p = 0;
        for (int k = 0; k + 1 < bkt[i].size(); k++) {
            if (bkt[i][k] == bkt[i][k + 1]) {
                p++;
                k++;
            }
        }
        int q = 0;
        for (int k = 0; k + 1 < bkt[j].size(); k++) {
            if (bkt[j][k] == bkt[j][k + 1]) {
                q++;
                k++;
            }
        }

        int is = bkt[i].size();
        int js = bkt[j].size();

        if (is > js) {
            swap(is, js);
            swap(p, q);
        }

        int sel = min((js - is) / 2, q);

        ans += sel;
        js -= sel * 2;
        ans += min(is, js);
    }

    cout << ans << endl;

    return 0;
}

