int binary_search(int *a, int find, int start, int end)
{
    if (start > end) {
        return -1;
    }

    int mid = (start + end) / 2;

    if (a[mid] == find) {
        return mid;
    }

    if (find < a[mid]) {
        end = mid - 1;
    } else {
        start = mid + 1;
    }

    return binary_search(a, find, start, end);
}

