  for(var i = 0, len = input.length-1; i < len; i++){
    var target = +input[i];
    if(target%2){
      console.log(0);
      continue;
    }

    var result = 0;
    for(var j = 1; primeNumbers[j] <= target/2; j++){
      for(var k = 1; k <= i; k++){
        if(primeNumbers[j] + primeNumbers[k] == target)
          result += 1;
      }
    }

    console.log(result);
    
  }
     
}
   
function calcPrimeNumbers(){
  var max = 50021;
  var primeNumbers = new Int8Array(max + 1);
   
  // 除外
  primeNumbers[0] = primeNumbers[1] = 1;
  for(var i = 2, maxI = ~~Math.sqrt(max); i <= maxI; i++){
    if(primeNumbers[i]){
      continue;
    }
       
    for(var j = (i<<1); j <= max; j+=i){
      primeNumbers[j] = 1;
    }
  }
   
  var primeNums = new Int32Array(5134 + 1);
  var c = 0;
  for(var i = 1; i <= max; i++){
    if(!primeNumbers[i]){
      primeNums[++c] = i;
    }
  }
     
  return primeNums;
}

/*
 * Problem: Print all the permutations of a string.
 *
 * Details: Permutation is "arrangement number" or "order". So problem is given a string, how many strings can we produce by rearranging them.
 *
 * Example: Permutations of ABC are ABC, ACB, BCA, BAC, CAB, CBA
 *
 * Approach: Lets take a backtracking approach. We select one letter, then recursively permute the remaining letters.
 *           At each step of permutation process, the given set will have two parts, a part we have already processed and the part we are yet to process.
 *           So, at ith step we exchange the i’th value with the value being chosen at that stage. 
 *
 */
#include <iostream>
#include <cstring>

/*
 * Helper routine to swap pointers
 */
void swap( char *a, char *b )
{
    char temp = *a;
    *a = *b;
    *b = temp;
}

/*
 * Function : Permute
 * Arg 1: c string
 * Arg 2: starting index of the string.
 * Arg 3: ending index of the string/
 */
void permute(char *str, int l, int r)
{
    if (l == r) 
    {
        std::cout << str << std::endl;
    }

    for (int i = l; i <= r; ++i) 
    {
        swap( (str + l), (str + i) );
        permute(str, l+1, r);
        swap( (str + l), (str + i) );
    }
}

int main()
{
    char str[] = "abc";
    std::cout << "Permutations of the string " << str << " are :\n";
    permute(str, 0, std::strlen(str)-1);
    return 0;
}

def isValid(s):
    stack = []

    for c in s:
        if c == '[' or c == '(' or c == '{':
            stack.append(c)
            
        else:
            if len(stack) == 0:
                return False
            
            open_paren = stack.pop()
            
            if not matches(open_paren,c):
                return False
            
    if len(stack) > 0:
        return False
            
    return True
    
def matches(p1,p2):
    if p1 == '(' and p2 == ')':
        return True
    
    elif p1 == '[' and p2 == ']':
        return True
    
    elif p1 == '{' and p2 == '}':
        return True
    
    else:
        return False

