void insert(BST *B, int x)
{
	if((*B)==NULL){
		(*B) = (BST)malloc(sizeof(BSTType));
		(*B)->elem = x;
		(*B)->left = (*B)->right = NULL;
	}else{
		if(x < (*B)->elem){
			insert(&(*B)->left, x);
		}else if(x > (*B)->elem){
			insert(&(*B)->right, x);
		}
	}
}

void deleteBST(BST *B, int x)
{
	BST temp;
	if((*B)==NULL){
		*B = NULL;
	}else if(x < (*B)->elem){
		deleteBST(&(*B)->left, x);
	}else if(x > (*B)->elem){
		deleteBST(&(*B)->right, x);
	}else{
		if((*B)->left == NULL && (*B)->right == NULL){
			*B = NULL;
		}else if((*B)->left == NULL){
			temp = (*B);
			(*B) = (*B)->right;
			free(temp);
		}else if((*B)->right == NULL){
			temp = (*B);
			(*B) = (*B)->left;
			free(temp);
		}else{
			temp = findMin((*B)->right);
			(*B)->elem = temp->elem;
			deleteBST(&(*B)->right, temp->elem);
		}
	}
}

BST findMin(BST B)
{
	if(B->left==NULL){
		return B;
	}else{
		return findMin(B->left);
	}
}

Boolean isMember(BST B, int x)
{
	if(B==NULL){
		return FALSE;
	}
	if(B->elem == x){
		return TRUE;
	}
	if(x < B->elem){
		return isMember(B->left, x);
	}else{
		return isMember(B->right, x);
	}
}

void Inorder(BST B)
{
	if(B!=NULL){
		Inorder(B->left);
		printf("%d\n", B->elem);
		Inorder(B->right);
	}
}

#include<stdio.h>


void mergeSort(int arr[], int l1, int r1, int l2, int r2)
{
    int temp[10], i, j, k=0;
    i = l1;
    j = l2;

    while((i <= r1) && (j <= r2))
    {
        if (arr[i] < arr[j])
        {
            temp[k++] = arr[i++];
        }
        else
        {
            temp[k++] = arr[j++];
        }
    }
    while(i <= r1)
    {
        temp[k++] = arr[i++];
    }
    while(j <= r2)
    { 
        temp[k++] = arr[j++];
    }


    for (i=l1, j=0; i<=r2; i++,j++)
    {
        arr[i] = temp[j];
    }
}


void partition(int arr[], int left, int right)
{
    int mid;

    if (left < right)
    {
        mid = (left + right)/2;
        partition(arr, left, mid);
        partition(arr, mid+1, right);
        mergeSort(arr, left, mid, mid+1, right);
    }
}


