/**
 * Insertion sort algorithm.
 *
 * @param int input Array to sort
 * @param int n Number of data in search array
 *
 * @return void
 */
void insertion_sort(int *input, int n)
{
    int gap, key;

    for (int i = 1; i < n; i++) {
        key = input[i];
        gap = i - 1;

        while (gap >= 0 && input[gap] > key) {
            input[gap + 1] = input[gap];
            gap--;
        }

        input[gap + 1] = key;
    }
}

