const int MAXN = 2e5 + 5;
typedef long long ll;
template <typename T> void chkmax(T &x, T y) {x = max(x, y); }
template <typename T> void chkmin(T &x, T y) {x = min(x, y); } 
template <typename T> void read(T &x) {
	x = 0; int f = 1;
	char c = getchar();
	for (; !isdigit(c); c = getchar()) if (c == '-') f = -f;
	for (; isdigit(c); c = getchar()) x = x * 10 + c - '0';
	x *= f;
}
int n; double a[MAXN], b[MAXN], f[MAXN], g[MAXN];
void init(int n) {
	static double s[MAXN], t[MAXN];
	double Max = 0; int pos = 1;
	for (int i = 1; i <= n; i++) {
		read(s[i]);
		if (s[i] > Max) {
			Max = s[i];
			pos = i;
		}
	}
	for (int i = 1; i <= n; i++)
		read(t[i]);
	int tot = 0;
	for (int i = pos; i <= n; i++, tot++)
		a[tot] = s[i], b[tot] = t[i];
	for (int i = 1; i <= pos; i++, tot++)
		a[tot] = s[i], b[tot] = t[i];
	for (int i = 1; i <= n; i++) {
		f[i] = f[i - 1] + b[i] * 2;
		g[i] = g[i - 1] + b[i] * i * 2;
	}
}
int top, s[MAXN], p[MAXN];
double query(int l, int r, int pos) {
	double delta = a[r] - a[l];
	double sum = f[r - 1] - f[l];
	double fun = g[r - 1] - g[l];
	double x = (delta - (sum * r - fun)) / (r - l);
	sum = f[pos - 1] - f[l], fun = g[pos - 1] - g[l];
	return a[l] + x * (pos - l) + (sum * pos - fun);
}
int main() {
	read(n), init(n), s[top = 1] = 0;
	for (int i = 1; i <= n; i++) {
		while (top >= 1 && query(s[top - 1], i, s[top]) > a[s[top]]) top--;
		s[++top] = i;
	}
	double ans = 0;
	for (int i = 1; i <= top; i++)
	for (int j = s[i - 1] + 1; j <= s[i]; j++)
		ans += query(s[i - 1], s[i], j);
	printf("%.10lf\n", ans / n);
	return 0;
}

