List Merge(List L1, List L2)
{
    List L = (List)malloc(sizeof(List));
    L->Next = NULL;
    List p = L1->Next, q = L2->Next, r = L;
    while (p && q)
    {
        if (p->Data < q->Data)
        {
            r->Next = p;
            p = p->Next;
        }
        else
        {
            r->Next = q;
            q = q->Next;
        }
        r = r->Next;
    }
    r->Next = p ? p : q;
    L1->Next = NULL;
    L2->Next = NULL;
    return L;
    
}

#include <cstdio>
