#include<bits/stdc++.h>
using namespace std;

using ld=long double;
const ld EPS=1e-10;
using P=complex<ld>;

void input(P &p){
    ld x,y;
    cin>>x>>y;
    p={x,y};
}
enum{WASTE,RAT,CAT};
using Graph=vector<vector<int>>;
int solve(int n){
    P ps,pt;
    input(ps),input(pt);
    vector<P> cs(n);
    vector<ld> r(n);
    for(int i=0;i<n;i++){
        input(cs[i]);
        cin>>r[i];
    }
    auto judge=[](P c,ld r,P x,P y){
        return abs(c-x)<r && abs(c-y)>r;
    };
    vector<int> type(n);
    for(int i=0;i<n;i++){
        if(judge(cs[i],r[i],ps,pt)){
            type[i]=RAT;
        }
        else if(judge(cs[i],r[i],pt,ps)){
            type[i]=CAT;
        }
        else{
            type[i]=WASTE;
        }
    }
    Graph g(n+2);
    const int RAT_V=n;
    const int CAT_V=n+1;
    g[RAT_V].push_back(CAT_V);
    for(int i=0;i<n;i++){
        if(type[i]==WASTE) continue;
        g[RAT_V].push_back(i);
        g[i].push_back(CAT_V);
        for(int j=0;j<n;j++){
            if(i==j) continue;
            ld d=abs(cs[i]-cs[j]);
            if(type[i]==RAT && type[j]==CAT){
                if(d>r[i]+r[j]+EPS){
                    g[i].push_back(j);    
                }
            }
            else if(type[i]==RAT && type[j]==RAT && r[i]<r[j]){
                if(d+EPS<r[j]-r[i]){
                    g[i].push_back(j);
                }
            }
            else if(type[j]==CAT && type[i]==CAT && r[i]>r[j]){
                if(d+EPS<r[i]-r[j]){
                    g[i].push_back(j);
                }
            }
        }
    }
    vector<int> idx(n);
    auto comp=[&](int lhs,int rhs){
        if(type[lhs]==WASTE && type[rhs]==WASTE) return r[lhs]<r[rhs];
        if(type[rhs]==WASTE) return true;
        if(type[lhs]==WASTE) return false;
        if(type[lhs]==RAT && type[rhs]==CAT) return true;
        if(type[rhs]==RAT && type[lhs]==CAT) return false;
        if(type[lhs]==RAT){
            return r[lhs]<r[rhs];
        }
        else{
            return r[lhs]>r[rhs];
        }
    };
    iota(idx.begin(),idx.end(),0);
    sort(idx.begin(),idx.end(),comp);
    vector<int> dp(n+2);
    for(auto to:g[RAT_V]) dp[to]=1;
    auto cmax=[](int &lhs,int rhs){lhs=max(lhs,rhs);};
    for(int i=0;i<n;i++){
        int id=idx[i];
        for(auto to:g[id]){
            cmax(dp[to],dp[id]+1);
        }
    }
    return dp[CAT_V]-1;
}
int main(){
    int n;
    while(cin>>n,n){
        cout<<solve(n)<<endl;        
    }
    return 0;
}

