link generate_circular_list(int len, int start)
{
  link t, head;
  int i;

  t = malloc(sizeof(link));
  if (t != NULL)
    {
      t->item = start;
      t->next = t;
      head = t;
    }
  for (i = 1; i < len; i++)
    {
      t = (t->next = (malloc(sizeof(link))));
      if (t != NULL)
	{
	  t->item = start + i;
	  t->next = head;
	}
    }
  return head;
}

void print_list(link t)
{
  link start = t;

  printf("%d ", t->item);
  t = t->next;
  while(t != start)
    {
      printf("%d ", t->item);
      t = t->next;
    }
  printf("\n");
}

void move_node (link x, link t)
{
  link nod = t->next, h = x->next;

  t->next = t->next->next;
  x->next = nod;
  nod->next = h;
}

