void solve1(int l, int r) {
	string res;
	int cur_a = l, cur_b = l;
	int cnt_a = 0, cnt_b = 0;
	int lastp = l-1;
	for (int i = 1; i <= (r-l+1)/2; i++) {
		while (cnt_a < i) {
			if (str[cur_a] == 'a') ++ cnt_a;
			++ cur_a;
		}
		while (cnt_b < i) {
			if (str[cur_b] == 'b') ++ cnt_b;
			++ cur_b;
		}
		if (cur_a - 1 > lastp) {
			lastp = cur_b - 1;
			res.push_back('a');
			res.push_back('b');
		}
	}
	if (mx.empty() || mx[0] == 'a') {
		mx = res;
		ans.push_back(mx);
	}
}

void solve2(int l, int r) {
	string t_mx;
	int cnt_a = 0, cnt_b = 0;
	int cur_a = r, cur_b = r;
	for (int i = 1; i <= (r-l+1)/2; i++) {
		while (cnt_a < i) {
			if (str[cur_a] == 'a') {
				vis[cur_a] = 1;
				++ cnt_a;
			}
			-- cur_a;
		}
		while (cnt_b < i) {
			if (str[cur_b] == 'b') {
				vis[cur_b] = 1;
				++ cnt_b;
			}
			-- cur_b;
		}
		string tmp;
		for (int j = l; j <= r; j++) if (vis[j]) tmp.push_back(str[j]);
		t_mx = max(t_mx, tmp);
	}
	if (t_mx >= mx) {
		mx = t_mx;
		ans.push_back(mx);
	}
}

void solve(int l, int r) {
	if (str[l] == 'a') solve1(l, r);
	else solve2(l, r);
}

