template<typename T>struct FFT{
   struct C{
      T x,y;
      C(T _x=0,T _y=0):x(_x),y(_y){}
      C operator~()const{return {x,-y};}
      C operator+(const C& c)const{return {x+c.x,y+c.y};}
      C operator-(const C& c)const{return {x-c.x,y-c.y};}
      C operator*(const C& c)const{return {x*c.x-y*c.y,x*c.y+y*c.x};}
   };
   vector<C> rt;
   FFT(int lg=20){
      rt.resize(1<<lg,1);
      rep(k,1,lg){
         int d=1<<k;
         rep(i,0,d){
            if(i&1)rt[d+i]=C(cos(2*M_PI*i/d),sin(2*M_PI*i/d));
            else rt[d+i]=rt[(d+i)>>1];
         }
      }
   }
   void fft(vector<C>& a,bool inv=0){
      int n=a.size(); assert((n&(n-1))==0);
      if(inv){
         for(int i=1;i<n;i<<=1)for(int j=0;j<n;j+=i*2)for(int k=0;k<i;k++){
            a[i+j+k]=a[i+j+k]*~rt[i*2+k]; C tmp=a[j+k]-a[i+j+k];
            a[j+k]=a[j+k]+a[i+j+k]; a[i+j+k]=tmp;
         } rep(i,0,n)a[i].x/=n,a[i].y/=n;
      }
      else{
         for(int i=n>>1;i;i>>=1)for(int j=0;j<n;j+=i*2)for(int k=0;k<i;k++){
            C tmp=a[j+k]-a[i+j+k];
            a[j+k]=a[j+k]+a[i+j+k]; a[i+j+k]=tmp*rt[i*2+k];
         }
      }
      for(int i=0,j=1;j<n-1;j++){
         for(int k=n>>1;k>(i^=k);k>>=1);
         if(j<i)swap(a[i],a[j]);
      }
   }
   vector<ll> conv(vector<ll> a,vector<ll> b){
      if(a.empty() or b.empty())return vector<ll>();
      int n=a.size()+b.size()-1,m=1; vector<ll> res(n); while(m<n)m<<=1;
      vector<C> c(m); rep(i,0,a.size())c[i].x=a[i]; rep(i,0,b.size())c[i].y=b[i];
      fft(c); C rad(0,-0.25/m);
      for(int i=0,j=0;i<=m/2;i++,j=(m-i)&(m-1)){
         C z=(c[j]*c[j]-~(c[i]*c[i]))*rad;
         if(i!=j)c[j]=(c[i]*c[i]-~(c[j]*c[j]))*rad;
         c[i]=z;
      } fft(c); rep(i,0,n)res[i]=c[i].x+0.5; return res;
   }
};

