// https://www.chilimath.com/algebra/advanced/cramers/2x2.html

/*
    determinant of 2x2 matrix
    [ a  b ]
    [ c  d ]
*/
function det(a, b, c, d) {
    return a * d - b * c;
}
/*
    ax+by=c
    dx+ey=f

    [a b] = [c]
    [d e] = [f]

    x matrix:
    [c b]
    [f e]

    y matrix:
    [a c]
    [d f]
*/
function solve_xy(a, b, c, d, e, f) {
    var D = det(a, b, d, e)
    var x = det(c, b, f, e) / D;
    var y = det(a, c, d, f) / D;
    return { x: x, y: y }
}
