ll add(ll x,ll y){
	return ((x+y)%mod+mod)%mod;
}
ll mul(ll x,ll y){
	return ((x*y)%mod+mod)%mod;
}
void dfs(int u,int f){
	for(auto v:g[u]){
		if(v==f)continue;
		d[v]=d[u]+1;
		dfs(v,u); 
	}
}
void dfs2(int u,int f){
	for(auto v:g[u]){
		if(v==f)continue;
		dfs2(v,u);
		if(vis[v])vis[u]=1;
	}
	if(vis[u])stk[++cnt]=u;
}
void sol(int u,int f){
	if(g[u].size()==1){
		if(vis[u])dp[u][0]=2,dp[u][1]=1;
		else dp[u][0]=3;
		return;
	}
	dp[u][0]=1;
	for(auto v:g[u]){
		if(v==f)continue;
		sol(v,u);
		rep(i,0,3)temp[i]=0;
		rep(i,0,3)rep(j,0,3)temp[min(2,i+j)]=add(temp[min(2,i+j)],mul(dp[u][i],dp[v][j]));
		rep(i,0,3)dp[u][i]=temp[i];
	//	cout<<v<<' '<<u<<" uv\n\n";
	//	cout<<dp[u][0]<<' '<<dp[u][1]<<' '<<dp[u][2]<<"checkdp\n";
	}
	dp[u][0]=add(dp[u][0],mul(2,dp[u][0]+dp[u][1]+dp[u][2])); 
}
