int Search(int *pa, int n, int k, int *count)
{
    int l = 0, r = n - 1, mid = l + r >> 1;
    *count = 0;
    while (l <= r)
    {
        (*count)++;
        if (pa[mid] == k)
            return mid;
        else if (pa[mid] < k)
            l = mid + 1;
        else
            r = mid - 1;
        mid = l + r >> 1;
    }
    return -1;
}

