    struct QNode *tmp;
    tmp = (struct QNode*)malloc(sizeof(struct QNode));
    if(tmp == NULL){
        exit(0);
    }
    tmp->value = value;
    tmp->next = NULL;
    if(q->front == NULL){
        q->front = q->rare = tmp;
    }
    else{
        q->rare->next = tmp;
        q->rare = tmp;
    }
}

