#define MAX_N 1000001
using namespace std;
typedef long long lld;

int n;
int niz[MAX_N];

//Quicksort algoritam za sortiranje niza
//Slozenost: O(n log n)

void qsort(int left, int right)
{
    if (left < right)
    {
        int i = left;
        int j = right;
        int pivot = niz[(i+j)/2];
        while (i<=j)
        {
            while (niz[i]<pivot) i++;
            while (niz[j]>pivot) j--;
            if (i<=j)
            {
                swap(niz[i], niz[j]);
                i++;
                j--;
            }
        }
        qsort(left,j);
        qsort(i,right);
    }
}

