class Stack:
    def __init__(self, size):
        self.size = size
        self.data = [None]* self.size
        self.top = -1
    def push(self,val):
        if not self.isFull():
            self.data.append(val)
            self.top += 1
    def isFull(self):
        if self.top >= self.size-1:
            return 1
        return  0
    def pop(self):
        poped = None
        if not self.isEmpty():
            poped = self.data.pop()
            self.top -= 1
        return poped
    def peek(self):
        return self.data[-1]
    def isEmpty(self):
        if self.top <= -1:
            return 1
        return 0
       




