public class Main {

  public static int countTriplets(int[]arr) {
    //write your code here
    // O(n^2)
    int count = 0;

    Arrays.sort(arr);

    for(int i = arr.length-1; i >= 0; i--)
    {
      int lo = 0;
      int hi = i-1;

      while(lo < hi)
      {
        if(arr[lo]+arr[hi] == arr[i])
        {
          count++;
          lo++;
          hi--;
        }
        else if(arr[lo]+arr[hi] < arr[i])
        {
          lo++;
        }
        else{
          hi--;
        }
      }
    }

    return count;
  }

