  if(mem[x][y]!=-2)return mem[x][y];
  int& a=mem[x][y];
  if(sim[x]!=sim[y]){
    if(sim[x]<sim[y])return a=1;
    else return a=-1;
  }
  if(nxt[x][0]==-1&&nxt[y][0]==-1)return a=0;
  int lx=nxt[x][0],rx=nxt[x][1];
  int ly=nxt[y][0],ry=nxt[y][1];
  assert(lx!=-1); assert(rx!=-1); assert(ly!=-1); assert(ry!=-1);
  if(cmp(lx,rx)==-1)swap(lx,rx);
  if(cmp(ly,ry)==-1)swap(ly,ry);
  if(cmp(lx,ly)!=0)return a=cmp(lx,ly);
  else return a=cmp(rx,ry);
}

void dfs(int v,bool isl){
  int l=nxt[v][0],r=nxt[v][1];
  if(l==-1)return ;
  int c=cmp(l,r);
  if((isl&&c==-1)||(!isl&&c==1)){
    swap(nxt[v][0],nxt[v][1]);
  }
  dfs(nxt[v][0],true);
  dfs(nxt[v][1],false);
}

void show(int v){
  int l=nxt[v][0],r=nxt[v][1];
  if(l==-1){
    cout<<"x"; return ;
  }
  cout<<"(";
  show(l);
  cout<<" ";
  show(r);
  cout<<")";
}

