        int n = input.nextInt();

        // Input the array
        int[][] arr = new int[n][n];
        System.out.println("Enter the elements: ");
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                System.out.print("arr[" + i + "][" + j + "] = ");
                arr[i][j] = input.nextInt();
            }
        }

        // Check for identity
        for (int i=0; i<n; i++) {
            for (int j=0; j<n; j++) {
                if (i == j) {
                    if (arr[i][j] != 1) {
