def quick_select(A,low,hi,k):
    if low==hi:
        return A[low]
    split=partition(A,low,hi)
    
    lenght=split-low+1
    if lenght==k:
        return A[split]
    elif k<lenght:
        return quick_select(A,low,split-1,k)
    else:
        return quick_select(A,split+1,hi,k-lenght)
    
    
