/*
Insertion sort

Worst complexity: O(n^2)
Average complexity: O(n^2)
Best complexity: O(n)
Space complexity: O(n)
*/
#include <stdio.h>

void insertionSort(int arr[], int n)
{
    for (int i = 1; i < n; i++)
    {
        int key = arr[i];
        int j = i - 1;

        while (j >= 0 && arr[j] > key)
        {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
}

