int insertionSort(){

    int arry[] = {3,5,6,9,4,1,2,7,8};
    
    int len = sizeof(arry)/sizeof(arry[0]);
    
    int i,j,temp;
    
    // 插入排序第一个元素本身就有序，所以从1开始
    for (i=1; i<len; i++)// 寻找元素arry[i]合适的插入位置
    {
        for (j = i; j>0; j--) // 从当期位置i比较，最多比较到j=1时，即
        {
            if (arry[j]<arry[j-1])
            {
                temp = arry[j];
                arry[j] = arry[j-1];
                arry[j-1] = temp;
                
            }else // j位置的元素已经大于等于j-1位置的元素终止循环
            {
                break;
            }
        }
    }
    
    printf("2.插入排序：");

    for(i=0;i<len;i++)
        printf("%d",arry[i]);
    
    printf("\n\n");

    return 0;
}

// 插入排序的优化
// 将三次赋值优化为一次赋值
int optimizationInsertionSort(){
    
    int arry[] = {3,5,6,9,4,1,2,7,8};
    
    int len = sizeof(arry)/sizeof(arry[0]);
    
    int i,j,temp;
    
    for (i = 1; i<len; i++)
    {
        temp = arry[i];// 保存当前位置i的元素，其中[0,i-1]已经有序
        
        for (j = i; j>0; j--)
        {
            if (temp<arry[j-1])
                arry[j] = arry[j-1]; // 后移一位
            else
                break;
        }
        arry[j] = temp; // 插入到合适的位置
    }
    
    printf("  插入排序的优化：");
    
    for(i=0;i<len;i++)
        printf("%d",arry[i]);
    
    printf("\n\n");
    
    return 0;
}

