void swap(int *x, int *y)
{
    int temp = *x;
    *x = *y;
    *y = temp;
}

void shellSort(int a[], int n)
{

    for (int gap = n / 2; gap >= 1; gap /= 2)
    {
        {
            for (int j = gap; j < n; j++)
            {
                for (int i = j - gap; i >= 0; i -= gap)
                {
                    if (a[i + gap] > a[i])
                    {
                        break;
                    }
                    else
                        swap(&a[i + gap], &a[i]);
                }
            }
        }
    }
}
